@font-face{font-family:'Cinzel';src:url('assets/fonts/cinzel-latin.woff2') format('woff2');font-weight:400 900;font-style:normal;font-display:swap}
@font-face{font-family:'Alegreya Sans';src:url('assets/fonts/alegreya-400.woff2') format('woff2');font-weight:400;font-style:normal;font-display:swap}
@font-face{font-family:'Alegreya Sans';src:url('assets/fonts/alegreya-500.woff2') format('woff2');font-weight:500;font-style:normal;font-display:swap}
@font-face{font-family:'Alegreya Sans';src:url('assets/fonts/alegreya-700.woff2') format('woff2');font-weight:700;font-style:normal;font-display:swap}
@font-face{font-family:'Alegreya Sans';src:url('assets/fonts/alegreya-italic.woff2') format('woff2');font-weight:400;font-style:italic;font-display:swap}

:root{
  --ink:#080b12;
  --ink2:#0d1320;
  --panel:rgba(12,18,30,.88);
  --panel2:rgba(20,28,44,.82);
  --gold:#d9b46a;
  --gold-bright:#f4dfa3;
  --gold-dark:#8c6a31;
  --parch:#f2e8d2;
  --muted:#a9b2c4;
  --blue:#7fd4ff;
  --violet:#b48cff;
  --red:#e25a4f;
  --green:#7ddc9a;
  --amber:#ffc45e;
  --line:rgba(217,180,106,.28);
  --line-soft:rgba(255,255,255,.08);
  --shadow:0 20px 70px rgba(0,0,0,.55);
  --serif:'Cinzel',Georgia,'Times New Roman',serif;
  --sans:'Alegreya Sans','Trebuchet MS',system-ui,sans-serif;
  --safe-t:env(safe-area-inset-top,0px);
  --safe-b:env(safe-area-inset-bottom,0px);
  --safe-l:env(safe-area-inset-left,0px);
  --safe-r:env(safe-area-inset-right,0px);
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{margin:0;height:100%;overflow:hidden;background:var(--ink);color:var(--parch);font-family:var(--sans);font-size:16px}
body{user-select:none;-webkit-user-select:none;touch-action:none;overscroll-behavior:none}
button,input{font:inherit;color:inherit}
button{cursor:pointer;border:0;background:none}
button:focus-visible,input:focus-visible{outline:2px solid var(--gold-bright);outline-offset:3px}
.hidden{display:none!important}
#app{position:fixed;inset:0;overflow:hidden;background:radial-gradient(circle at 50% 40%,#101a2c,#05070c 75%)}
#game-canvas{position:absolute;inset:0;width:100%;height:100%;display:block;image-rendering:auto}

/* ---------- shared chrome ---------- */
.glass{background:linear-gradient(160deg,rgba(18,27,44,.92),rgba(8,12,20,.9));border:1px solid var(--line);box-shadow:var(--shadow),inset 0 1px 0 rgba(255,255,255,.06);backdrop-filter:blur(10px)}
.glass::before,.glass::after{content:'';position:absolute;width:14px;height:14px;border:1px solid var(--gold);opacity:.65;pointer-events:none}
.glass::before{left:-1px;top:-1px;border-right:0;border-bottom:0}
.glass::after{right:-1px;bottom:-1px;border-left:0;border-top:0}
.eyebrow,.quest-eyebrow,.cine-eyebrow{font-family:var(--serif);font-size:10px;letter-spacing:.32em;text-transform:uppercase;color:var(--gold);font-weight:700}
.ghost-btn{padding:10px 16px;border:1px solid var(--line);background:rgba(255,255,255,.03);color:var(--muted);border-radius:4px;font-family:var(--serif);font-size:11px;letter-spacing:.16em;text-transform:uppercase;transition:.2s}
.ghost-btn:hover{color:var(--gold-bright);border-color:var(--gold);background:rgba(217,180,106,.08)}
.menu-btn{display:flex;align-items:center;gap:14px;width:100%;text-align:left;padding:12px 18px;border:1px solid rgba(217,180,106,.22);background:linear-gradient(90deg,rgba(16,24,40,.9),rgba(12,18,30,.5));border-radius:3px;color:var(--parch);position:relative;overflow:hidden;transition:transform .18s,border-color .18s,background .18s}
.menu-btn::after{content:'';position:absolute;left:0;top:0;bottom:0;width:2px;background:var(--gold);transform:scaleY(0);transition:.2s}
.menu-btn:hover,.menu-btn:focus-visible{transform:translateX(4px);border-color:var(--gold);background:linear-gradient(90deg,rgba(38,48,70,.95),rgba(14,20,32,.6))}
.menu-btn:hover::after{transform:scaleY(1)}
.menu-btn .mb-glyph{font-size:20px;color:var(--gold);width:26px;text-align:center;text-shadow:0 0 14px rgba(217,180,106,.6)}
.menu-btn b{display:block;font-family:var(--serif);font-weight:600;font-size:15px;letter-spacing:.08em}
.menu-btn small{display:block;color:var(--muted);font-size:12px;margin-top:2px}
.menu-btn.primary{border-color:rgba(217,180,106,.55);background:linear-gradient(90deg,rgba(64,52,29,.7),rgba(20,24,34,.8))}
.menu-btn.primary b{color:var(--gold-bright)}
.menu-btn.compact{width:auto;padding:9px 18px}
.menu-btn:disabled{opacity:.35;cursor:not-allowed;transform:none}
kbd{display:inline-flex;align-items:center;justify-content:center;min-width:20px;height:19px;padding:0 5px;border:1px solid rgba(255,255,255,.22);border-bottom-width:2px;border-radius:3px;font-family:var(--sans);font-size:10px;color:var(--parch);background:rgba(255,255,255,.06);vertical-align:middle}

/* ---------- boot ---------- */
.boot{position:fixed;inset:0;z-index:200;background:radial-gradient(circle at 50% 45%,#17243a,#04060a 70%);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;transition:opacity .9s,visibility .9s}
.boot.off{opacity:0;visibility:hidden}
.boot-mark{font-size:42px;color:var(--gold);animation:pulse 2.2s ease-in-out infinite;text-shadow:0 0 30px rgba(217,180,106,.8)}
.boot h1{font-family:var(--serif);font-size:clamp(18px,3vw,30px);letter-spacing:.3em;margin:0;font-weight:600;color:var(--gold-bright)}
.boot-bar{width:min(300px,60vw);height:2px;background:rgba(255,255,255,.1);overflow:hidden}
.boot-bar i{display:block;height:100%;width:40%;background:linear-gradient(90deg,transparent,var(--gold),transparent);animation:bootbar 1.4s ease-in-out infinite}
.boot p{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:var(--muted);margin:0}
@keyframes bootbar{0%{transform:translateX(-120%)}100%{transform:translateX(320%)}}
@keyframes pulse{0%,100%{opacity:.6;transform:scale(.96)}50%{opacity:1;transform:scale(1.06)}}

/* ---------- screens ---------- */
.screen{position:absolute;inset:0;z-index:20}
.title-screen{overflow:hidden;background:#05070c}
#title-canvas{position:absolute;inset:0;width:100%;height:100%}
.title-vignette{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 45%,transparent 30%,rgba(3,5,10,.55) 70%,rgba(2,3,7,.95) 100%),linear-gradient(180deg,rgba(4,6,12,.5),transparent 30%,transparent 65%,rgba(3,5,9,.95))}
.title-content{position:relative;z-index:2;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:calc(var(--safe-t) + 3vh) 5vw calc(var(--safe-b) + 2vh);text-align:center}
.title-kicker{font-family:var(--serif);font-size:clamp(8px,1.1vw,11px);letter-spacing:.42em;color:rgba(244,223,163,.72);margin-bottom:10px;text-shadow:0 2px 18px #000}
.game-logo{font-family:var(--serif);font-weight:700;font-size:clamp(34px,6.2vw,78px);line-height:.92;letter-spacing:.06em;margin:0;color:transparent;background:linear-gradient(180deg,#fff8df 5%,#f0d48d 38%,#c89a45 62%,#f7e7b4 100%);-webkit-background-clip:text;background-clip:text;filter:drop-shadow(0 5px 24px rgba(0,0,0,.8)) drop-shadow(0 0 38px rgba(217,180,106,.25))}
.game-logo span{display:inline-block;font-size:.42em;letter-spacing:.24em;vertical-align:.55em;color:transparent;background:linear-gradient(180deg,#f4dfa3,#a87c36);-webkit-background-clip:text;background-clip:text}
.title-rule{display:flex;align-items:center;gap:14px;width:min(420px,72vw);margin:16px auto 12px;color:var(--gold)}
.title-rule i{flex:1;height:1px;background:linear-gradient(90deg,transparent,rgba(217,180,106,.7))}
.title-rule i:last-child{background:linear-gradient(90deg,rgba(217,180,106,.7),transparent)}
.title-rule b{font-size:10px;text-shadow:0 0 12px rgba(217,180,106,.8)}
.title-tagline{font-size:clamp(12px,1.4vw,15px);line-height:1.6;color:#c7ccd7;max-width:540px;margin:0 0 20px;text-shadow:0 2px 14px #000}
.title-menu{width:min(390px,88vw);display:flex;flex-direction:column;gap:7px}
.title-menu .menu-btn{padding:9px 16px;background:linear-gradient(90deg,rgba(10,15,25,.7),rgba(10,15,25,.2));border-color:rgba(217,180,106,.18)}
.title-menu .menu-btn small{font-size:11px}
.title-menu .menu-btn b{font-size:14px}
.title-foot{position:absolute;bottom:calc(var(--safe-b) + 12px);left:0;right:0;display:flex;justify-content:space-between;padding:0 26px;font-size:10px;letter-spacing:.08em;color:rgba(180,190,205,.45);text-transform:uppercase}
.title-side-note{position:absolute;right:calc(var(--safe-r) + 18px);top:calc(var(--safe-t) + 16px);font-family:var(--serif);font-size:9px;letter-spacing:.22em;color:rgba(217,180,106,.5);text-transform:uppercase;writing-mode:vertical-rl}
@media (max-height:620px){
  .title-content{justify-content:center;padding-top:calc(var(--safe-t) + 8px)}
  .title-tagline{display:none}.title-rule{margin:8px auto}.title-menu{gap:4px}
  .title-menu .menu-btn{padding:6px 14px}.title-menu .menu-btn small{display:none}
  .game-logo{font-size:clamp(28px,5vw,54px)}.title-foot{font-size:8px}
}

/* ---------- creation ---------- */
.creation-screen{background:radial-gradient(circle at 30% 30%,#17253b,#070a12 70%);display:flex;flex-direction:column;padding:calc(var(--safe-t) + 16px) calc(var(--safe-r) + 24px) calc(var(--safe-b) + 16px) calc(var(--safe-l) + 24px)}
.creation-bg{position:absolute;inset:0;background:radial-gradient(circle at 18% 45%,rgba(217,180,106,.13),transparent 35%),radial-gradient(circle at 80% 20%,rgba(127,212,255,.08),transparent 40%),repeating-linear-gradient(115deg,transparent 0 80px,rgba(255,255,255,.012) 80px 81px);pointer-events:none}
.creation-head{position:relative;z-index:2;display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:12px;flex:0 0 auto}
.creation-head h2{font-family:var(--serif);font-weight:600;font-size:clamp(16px,2.2vw,26px);margin:4px 0 0;letter-spacing:.04em}
.creation-grid{position:relative;z-index:2;display:grid;grid-template-columns:minmax(230px,.75fr) minmax(430px,1.55fr);gap:16px;flex:1;min-height:0}
.creation-preview{position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;overflow:hidden;border-radius:6px;background:radial-gradient(circle at 50% 35%,rgba(127,212,255,.1),rgba(6,10,18,.92) 70%)}
.creation-preview::after{content:'';position:absolute;inset:10px;border:1px solid rgba(217,180,106,.15);pointer-events:none}
#preview-canvas{width:100%;height:100%;max-height:calc(100% - 88px);object-fit:contain}
.preview-plate{text-align:center;padding:4px 10px 8px}
#preview-name{font-family:var(--serif);font-size:22px;letter-spacing:.18em;color:var(--gold-bright)}
#preview-title{font-size:11px;letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}
.preview-hint{position:absolute;bottom:10px;font-size:10px;font-style:italic;color:rgba(200,210,225,.4)}
.creation-form{position:relative;border-radius:6px;padding:14px 18px;overflow-y:auto;overscroll-behavior:contain;display:flex;flex-direction:column;gap:11px}
.creation-form::-webkit-scrollbar{width:6px}.creation-form::-webkit-scrollbar-thumb{background:rgba(217,180,106,.3);border-radius:3px}
.form-block{border-bottom:1px solid var(--line-soft);padding-bottom:10px}
.form-block:last-of-type{border:0}
.form-block label,.block-head span{display:block;font-family:var(--serif);font-size:11px;letter-spacing:.18em;text-transform:uppercase;color:var(--gold);margin-bottom:5px}
.block-head{display:flex;justify-content:space-between;align-items:baseline;gap:8px}
.block-head small{color:var(--muted);font-size:10px;text-align:right}
#char-name{width:100%;background:rgba(0,0,0,.35);border:1px solid var(--line);border-radius:3px;padding:9px 12px;font-family:var(--serif);font-size:18px;letter-spacing:.1em;color:var(--gold-bright)}
.name-row{display:flex;gap:6px;margin-top:6px;flex-wrap:wrap}
.chip{padding:4px 10px;border:1px solid var(--line-soft);border-radius:20px;font-size:10px;color:var(--muted);background:rgba(255,255,255,.03)}
.chip:hover{color:var(--gold);border-color:var(--line)}
.option-rows{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.option-row{display:flex;align-items:center;justify-content:space-between;gap:6px;background:rgba(255,255,255,.025);border:1px solid var(--line-soft);border-radius:3px;padding:4px 6px;min-height:34px}
.option-row .opt-label{font-size:9px;letter-spacing:.12em;text-transform:uppercase;color:var(--muted);flex:0 0 52px}
.option-row .opt-value{flex:1;text-align:center;font-size:11px;color:var(--parch);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.option-row button{width:22px;height:22px;border:1px solid var(--line-soft);border-radius:2px;color:var(--gold);font-size:11px;line-height:1;background:rgba(0,0,0,.2)}
.option-row button:hover{background:rgba(217,180,106,.15);border-color:var(--line)}
.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}
.stat-cell{background:rgba(255,255,255,.025);border:1px solid var(--line-soft);padding:5px 6px;border-radius:3px;text-align:center}
.stat-cell .sname{display:block;font-size:9px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted)}
.stat-cell .sval{display:flex;align-items:center;justify-content:center;gap:5px;margin-top:2px}
.stat-cell .sval b{font-family:var(--serif);font-size:17px;color:var(--gold-bright);min-width:20px}
.stat-cell button{width:17px;height:17px;border:1px solid var(--line-soft);border-radius:2px;color:var(--gold);font-size:10px;line-height:1;background:rgba(0,0,0,.2)}
.stat-cell button:disabled{opacity:.2}
.stat-note{font-size:10px;color:var(--muted);margin:5px 0 0;font-style:italic}
.creation-actions{display:flex;gap:10px;align-items:stretch;margin-top:auto;padding-top:4px}
.creation-actions .menu-btn{flex:1}
@media (max-width:900px){
  .creation-screen{padding:calc(var(--safe-t) + 8px) calc(var(--safe-r) + 10px) calc(var(--safe-b) + 8px) calc(var(--safe-l) + 10px)}
  .creation-head{margin-bottom:6px}.creation-head h2{font-size:14px}.creation-head .eyebrow{display:none}
  .creation-grid{grid-template-columns:minmax(170px,.55fr) minmax(360px,1.45fr);gap:8px}
  .creation-preview .preview-hint{display:none}.creation-form{padding:8px 10px;gap:6px}
  #preview-name{font-size:16px}.preview-plate{padding-bottom:2px}
  .form-block{padding-bottom:6px}.option-rows{gap:4px}.option-row{min-height:29px}
  .stat-cell{padding:3px}.stat-cell .sval b{font-size:14px}
  .creation-actions .menu-btn small{display:none}
}
@media (max-height:560px){
  .creation-head h2{display:none}.creation-head{align-items:center}
  .preview-hint{display:none}.preview-plate{display:none}
  .form-block label,.block-head span{font-size:9px}
  .creation-form{font-size:13px}.option-row{min-height:26px}
}

/* ---------- HUD ---------- */
#hud{position:absolute;inset:0;z-index:10;pointer-events:none;font-size:14px}
#hud button{pointer-events:auto}
.hud-vitals{position:absolute;left:calc(var(--safe-l) + 14px);top:calc(var(--safe-t) + 12px);display:flex;gap:9px;padding:8px 12px 8px 8px;border-radius:4px;width:min(310px,34vw);min-width:240px}
.portrait-frame{position:relative;width:64px;height:64px;flex:0 0 auto;border:1px solid var(--line);background:radial-gradient(circle,#1e2b42,#0a101b);overflow:hidden;border-radius:2px}
.portrait-frame canvas{width:100%;height:100%;display:block}
.element-chip{position:absolute;bottom:0;left:0;right:0;text-align:center;font-size:7px;letter-spacing:.18em;background:rgba(0,0,0,.65);color:var(--gold);padding:1px 0}
.vitals-body{flex:1;min-width:0}
.vitals-head{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:2px}
.vitals-head strong{font-family:var(--serif);font-size:13px;letter-spacing:.08em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.vitals-head span{font-size:9px;color:var(--gold);letter-spacing:.08em}
.bar{position:relative;height:10px;background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.1);border-radius:2px;margin-bottom:2px;overflow:hidden}
.bar i{position:absolute;inset:0;transform-origin:left;transition:transform .15s;border-radius:1px}
.bar b{position:absolute;right:3px;top:50%;transform:translateY(-50%);font-size:7px;font-weight:500;letter-spacing:.04em;color:#fff;text-shadow:0 1px 2px #000;opacity:.85}
.bar-hp i{background:linear-gradient(90deg,#8e2d33,#e25a4f 55%,#ff8c72)}
.bar-mp i{background:linear-gradient(90deg,#2e5f9e,#5aa7e2 55%,#9ad8ff)}
.bar-st i{background:linear-gradient(90deg,#6b7a2f,#b9c95e 55%,#e8e89a)}
.xp-line{position:relative;height:4px;background:rgba(0,0,0,.4);border-radius:1px;margin-top:3px}
.xp-line i{position:absolute;inset:0;transform-origin:left;background:linear-gradient(90deg,#8c6a31,#f4dfa3);border-radius:1px;transition:transform .2s}
.xp-line span{position:absolute;right:0;top:5px;font-size:7px;color:rgba(255,255,255,.45)}
.hud-map{position:absolute;right:calc(var(--safe-r) + 14px);top:calc(var(--safe-t) + 12px);width:min(230px,24vw);min-width:170px;padding:6px;border-radius:4px}
.map-head{display:flex;justify-content:space-between;align-items:baseline;font-size:8px;letter-spacing:.1em;color:var(--gold);text-transform:uppercase;padding:0 2px 3px}
.map-head span:last-child{color:var(--muted);font-size:8px;letter-spacing:.04em;text-transform:none}
#minimap{width:100%;height:auto;display:block;background:rgba(0,0,0,.35);border:1px solid var(--line-soft);border-radius:2px}
.map-foot{display:flex;justify-content:space-between;font-size:8px;color:var(--muted);padding:3px 2px 0}
#gold-label{color:var(--gold)}
.quest-tracker{position:absolute;right:calc(var(--safe-r) + 14px);top:calc(var(--safe-t) + 158px);width:min(230px,24vw);min-width:170px;padding:8px 10px;border-radius:4px;border-left:2px solid var(--gold)}
.quest-tracker .quest-eyebrow{font-size:7px;letter-spacing:.18em;margin-bottom:2px}
#quest-title{font-family:var(--serif);font-size:12px;color:var(--gold-bright);line-height:1.2}
#quest-objective{font-size:10px;color:#cbd2df;margin-top:2px;line-height:1.3}
.hud-top-actions{position:absolute;left:50%;top:calc(var(--safe-t) + 12px);transform:translateX(-50%);display:flex;gap:6px}
.icon-btn{width:48px;padding:4px 3px 3px;display:flex;flex-direction:column;align-items:center;gap:0;background:rgba(10,15,25,.72);border:1px solid var(--line);border-radius:3px;color:var(--parch);backdrop-filter:blur(6px)}
.icon-btn span{font-size:15px;color:var(--gold);line-height:1.1}
.icon-btn small{font-size:7px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.icon-btn:hover{border-color:var(--gold);background:rgba(30,38,55,.9)}
.companion-chip{position:absolute;left:calc(var(--safe-l) + 14px);top:calc(var(--safe-t) + 88px);display:flex;align-items:center;gap:7px;padding:4px 9px 4px 4px;border-radius:20px}
.companion-chip canvas{width:30px;height:30px;border-radius:50%;background:radial-gradient(circle,#22354f,#0a0f19);border:1px solid var(--line)}
.companion-chip span{display:block;font-size:9px;letter-spacing:.06em;color:var(--gold-bright);line-height:1.1}
.companion-chip b{display:block;font-size:7px;font-weight:400;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}
.boss-bar{position:absolute;left:50%;top:calc(var(--safe-t) + 76px);transform:translateX(-50%);width:min(520px,60vw);padding:7px 12px 9px;background:linear-gradient(180deg,rgba(20,10,14,.8),rgba(8,8,12,.65));border:1px solid rgba(226,90,79,.3);border-radius:3px}
.boss-title{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:4px}
.boss-title span{font-family:var(--serif);font-size:13px;letter-spacing:.14em;color:#ffd8c8}
.boss-title em{font-size:8px;font-style:normal;letter-spacing:.2em;color:#ff8f7d}
.boss-bar .bar{height:8px;margin:0;border-color:rgba(255,255,255,.15)}
.boss-bar .bar i{background:linear-gradient(90deg,#5c151b,#c33a3a 50%,#ff806a);transition:transform .2s}
.interact-prompt,.capture-prompt{position:absolute;left:50%;bottom:calc(var(--safe-b) + 120px);transform:translateX(-50%);display:flex;align-items:center;gap:8px;padding:7px 14px;background:rgba(6,10,18,.88);border:1px solid var(--line);border-radius:30px;font-size:12px;letter-spacing:.04em;box-shadow:0 8px 30px rgba(0,0,0,.5)}
.interact-prompt kbd,.capture-prompt kbd{background:rgba(217,180,106,.15);border-color:var(--gold);color:var(--gold-bright)}
.capture-prompt{border-color:rgba(180,140,255,.6);box-shadow:0 0 30px rgba(180,140,255,.25);bottom:calc(var(--safe-b) + 160px)}
.capture-prompt kbd{border-color:var(--violet);color:#dcc9ff;background:rgba(180,140,255,.15)}
.capture-prompt i{font-style:normal;color:#dcc9ff;font-size:10px}
.hint{position:absolute;left:50%;bottom:calc(var(--safe-b) + 70px);transform:translateX(-50%);max-width:min(620px,80vw);text-align:center;font-size:11px;line-height:1.4;color:#e7e2d4;background:rgba(6,10,18,.82);border:1px solid var(--line-soft);padding:7px 14px;border-radius:3px;transition:opacity .4s}
.keys-hint{position:absolute;left:50%;bottom:calc(var(--safe-b) + 8px);transform:translateX(-50%);font-size:8px;letter-spacing:.05em;color:rgba(255,255,255,.3);white-space:nowrap;text-align:center}
@media (max-width:900px){
  .hud-vitals{width:min(250px,46vw);min-width:180px;padding:5px 7px 5px 5px;left:calc(var(--safe-l) + 8px);top:calc(var(--safe-t) + 8px)}
  .portrait-frame{width:46px;height:46px}.vitals-head strong{font-size:10px}.vitals-head span{font-size:7px}
  .bar{height:7px}.bar b{font-size:6px}.xp-line{display:none}
  .hud-map{width:min(140px,23vw);min-width:100px;right:calc(var(--safe-r) + 8px);top:calc(var(--safe-t) + 8px);padding:4px}
  .map-head{font-size:6px}.map-foot{font-size:6px}
  .quest-tracker{display:none}
  .hud-top-actions{top:calc(var(--safe-t) + 8px);left:auto;right:calc(var(--safe-r) + 8px);transform:none;margin-top:0}
  .icon-btn{width:32px;height:32px;padding:2px}.icon-btn span{font-size:12px}.icon-btn small{display:none}
  .hud-map{top:calc(var(--safe-t) + 46px)}
  .companion-chip{left:calc(var(--safe-l) + 8px);top:calc(var(--safe-t) + 58px);padding:2px 6px 2px 2px}
  .companion-chip canvas{width:22px;height:22px}.companion-chip span{font-size:7px}.companion-chip b{display:none}
  .keys-hint{display:none}
  .interact-prompt{bottom:calc(var(--safe-b) + 105px);font-size:10px;padding:5px 10px}
  .capture-prompt{bottom:calc(var(--safe-b) + 140px);font-size:10px;padding:5px 10px}
  .hint{bottom:calc(var(--safe-b) + 80px);font-size:9px}
  .boss-bar{width:56vw;top:calc(var(--safe-t) + 46px)}
}
@media (max-height:480px){
  .hud-vitals{width:200px;min-width:0}.portrait-frame{width:38px;height:38px}
  .hud-map{width:96px;min-width:0}.quest-tracker{display:none}
  .companion-chip{display:none}
}

/* ---------- touch ---------- */
.touch{position:absolute;inset:0;z-index:12;pointer-events:none}
.joystick{position:absolute;left:calc(var(--safe-l) + 26px);bottom:calc(var(--safe-b) + 26px);width:118px;height:118px;border-radius:50%;pointer-events:auto;touch-action:none;background:radial-gradient(circle,rgba(255,255,255,.04),rgba(8,12,20,.35));border:1px solid rgba(217,180,106,.2)}
.joy-ring{position:absolute;inset:18px;border-radius:50%;border:1px dashed rgba(217,180,106,.18)}
.joy-knob{position:absolute;left:50%;top:50%;width:48px;height:48px;margin:-24px 0 0 -24px;border-radius:50%;background:radial-gradient(circle at 35% 30%,rgba(244,223,163,.9),rgba(140,106,49,.65));box-shadow:0 4px 18px rgba(0,0,0,.5),0 0 18px rgba(217,180,106,.2);border:1px solid rgba(255,255,255,.4);transition:transform .05s}
.touch-actions{position:absolute;right:calc(var(--safe-r) + 18px);bottom:calc(var(--safe-b) + 14px);width:230px;height:180px;pointer-events:none}
.tbtn{position:absolute;pointer-events:auto;touch-action:none;border-radius:50%;background:radial-gradient(circle at 35% 30%,rgba(40,52,72,.92),rgba(8,12,20,.88));border:1px solid rgba(217,180,106,.38);color:var(--gold-bright);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:0;box-shadow:0 4px 16px rgba(0,0,0,.45),inset 0 1px 0 rgba(255,255,255,.1);transition:transform .08s,background .08s}
.tbtn span{font-size:20px;line-height:1}.tbtn small{font-size:7px;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);line-height:1.1;margin-top:1px}
.tbtn.pressed,.tbtn:active{transform:scale(.9);background:radial-gradient(circle at 35% 30%,rgba(217,180,106,.55),rgba(60,45,20,.9))}
.tbtn-attack{right:8px;bottom:44px;width:78px;height:78px;border-color:rgba(244,223,163,.65)}
.tbtn-attack span{font-size:28px;color:#fff1c9}
.tbtn-heavy{right:80px;bottom:0;width:54px;height:54px}
.tbtn-dodge{right:0;bottom:126px;width:54px;height:54px}
.tbtn-block{right:88px;bottom:74px;width:54px;height:54px}
.tbtn-spell{right:148px;bottom:18px;width:50px;height:50px}
.tbtn-creature{right:156px;bottom:92px;width:48px;height:48px}
.tbtn-potion{right:150px;bottom:150px;width:44px;height:44px}
.tbtn-interact{left:50%;bottom:140px;width:62px;height:62px;transform:translateX(-50%);border-color:var(--gold);background:radial-gradient(circle,rgba(217,180,106,.3),rgba(8,12,20,.9));animation:promptPulse 1.4s infinite}
.tbtn-capture{left:50%;bottom:210px;width:62px;height:62px;transform:translateX(-50%);border-color:var(--violet);background:radial-gradient(circle,rgba(180,140,255,.3),rgba(8,12,20,.9));animation:promptPulse 1.2s infinite}
@keyframes promptPulse{0%,100%{box-shadow:0 0 0 0 rgba(217,180,106,.3)}50%{box-shadow:0 0 0 12px rgba(217,180,106,0)}}
@media (max-width:900px){
  .joystick{width:96px;height:96px;left:calc(var(--safe-l) + 16px);bottom:calc(var(--safe-b) + 16px)}
  .joy-knob{width:40px;height:40px;margin:-20px 0 0 -20px}
  .touch-actions{transform:scale(.82);transform-origin:bottom right;right:calc(var(--safe-r) + 6px);bottom:calc(var(--safe-b) + 4px)}
}
@media (max-height:480px){
  .joystick{width:84px;height:84px}.touch-actions{transform:scale(.72)}
}

/* ---------- overlay menus ---------- */
.overlay{position:absolute;inset:0;z-index:40;background:rgba(3,5,10,.72);backdrop-filter:blur(5px);display:flex;align-items:center;justify-content:center;padding:calc(var(--safe-t) + 14px) calc(var(--safe-r) + 18px) calc(var(--safe-b) + 14px) calc(var(--safe-l) + 18px);animation:overlayIn .22s ease-out}
@keyframes overlayIn{from{opacity:0}to{opacity:1}}
.menu-shell{width:min(1180px,96vw);height:min(760px,92vh);display:grid;grid-template-columns:200px 1fr;background:linear-gradient(150deg,rgba(15,22,36,.98),rgba(6,9,16,.98));border:1px solid var(--line);box-shadow:0 30px 100px rgba(0,0,0,.8);border-radius:5px;overflow:hidden;position:relative}
.menu-shell::after{content:'';position:absolute;inset:7px;border:1px solid rgba(217,180,106,.1);pointer-events:none;border-radius:3px}
.menu-side{padding:20px 12px;border-right:1px solid var(--line-soft);display:flex;flex-direction:column;background:linear-gradient(180deg,rgba(217,180,106,.05),transparent 30%)}
.menu-brand{font-family:var(--serif);font-size:10px;letter-spacing:.2em;color:var(--gold);text-align:center;padding-bottom:14px;border-bottom:1px solid var(--line-soft);margin-bottom:12px}
.menu-brand b{display:block;font-size:14px;letter-spacing:.1em;color:var(--gold-bright);margin-top:3px}
.menu-tabs{display:flex;flex-direction:column;gap:3px;flex:1;overflow-y:auto}
.tab-btn{display:flex;align-items:center;gap:9px;padding:8px 10px;border-radius:3px;font-family:var(--serif);font-size:11px;letter-spacing:.08em;color:var(--muted);text-align:left;border:1px solid transparent}
.tab-btn span{width:18px;text-align:center;color:var(--gold);font-size:13px}
.tab-btn:hover{background:rgba(255,255,255,.04);color:var(--parch)}
.tab-btn.active{background:linear-gradient(90deg,rgba(217,180,106,.14),transparent);border-color:rgba(217,180,106,.2);color:var(--gold-bright)}
.menu-side-foot{font-size:9px;color:rgba(255,255,255,.28);text-align:center;padding-top:8px;line-height:1.5}
.menu-main{display:flex;flex-direction:column;min-width:0;overflow:hidden}
.menu-head{display:flex;justify-content:space-between;align-items:center;padding:15px 22px;border-bottom:1px solid var(--line-soft);flex:0 0 auto}
.menu-head h2{font-family:var(--serif);font-weight:600;font-size:20px;letter-spacing:.1em;margin:0;color:var(--gold-bright)}
.menu-head p{margin:2px 0 0;font-size:10px;color:var(--muted)}
.menu-head .close-btn{width:34px;height:34px;border:1px solid var(--line);border-radius:3px;color:var(--gold);font-size:17px}
.menu-head .close-btn:hover{background:rgba(217,180,106,.12)}
.menu-body{padding:16px 22px;overflow-y:auto;overscroll-behavior:contain;flex:1;min-height:0}
.menu-body::-webkit-scrollbar{width:7px}.menu-body::-webkit-scrollbar-thumb{background:rgba(217,180,106,.3);border-radius:4px}
.menu-grid{display:grid;gap:10px}
.cols-2{grid-template-columns:1fr 1fr}.cols-3{grid-template-columns:repeat(3,1fr)}.cols-4{grid-template-columns:repeat(4,1fr)}
.panel{border:1px solid var(--line-soft);background:rgba(255,255,255,.025);border-radius:4px;padding:12px}
.panel h3{margin:0 0 8px;font-family:var(--serif);font-size:12px;letter-spacing:.14em;color:var(--gold);font-weight:600;text-transform:uppercase}
.stat-line{display:flex;justify-content:space-between;gap:8px;padding:4px 0;border-bottom:1px dotted rgba(255,255,255,.07);font-size:12px}
.stat-line span{color:var(--muted)}.stat-line b{color:var(--parch);font-weight:500}
.stat-line b.up{color:var(--green)}.stat-line b.down{color:var(--red)}
.big-stat{display:flex;align-items:baseline;gap:6px}
.big-stat b{font-family:var(--serif);font-size:26px;color:var(--gold-bright);font-weight:600}
.big-stat small{font-size:9px;color:var(--muted);letter-spacing:.1em;text-transform:uppercase}
.slot-grid{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.slot{display:flex;align-items:center;gap:8px;padding:8px;border:1px solid var(--line-soft);background:rgba(0,0,0,.18);border-radius:3px;text-align:left;width:100%}
