.mini-btn.danger{color:var(--red);border-color:rgba(226,90,79,.3)}
.rarity-common{color:#cfd6e2}.rarity-uncommon{color:#7ddc9a}.rarity-rare{color:#7fb9ff}.rarity-epic{color:#c79bff}.rarity-legendary{color:#ffd06a}
.attr-row{display:flex;align-items:center;justify-content:space-between;gap:6px;padding:5px 0;border-bottom:1px dotted rgba(255,255,255,.07)}
.attr-row .an{font-size:11px;color:var(--muted);flex:0 0 88px}.attr-row .av{font-family:var(--serif);font-size:15px;color:var(--gold-bright);min-width:24px;text-align:center}
.attr-row .ad{font-size:9px;color:rgba(255,255,255,.4);flex:1}
.attr-row button{width:22px;height:22px;border:1px solid var(--line);border-radius:2px;color:var(--gold);font-size:12px;background:rgba(0,0,0,.25)}
.attr-row button:disabled{opacity:.25}
.skill-tree{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.skill-branch h3{font-family:var(--serif);font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:var(--gold);text-align:center;margin:0 0 8px;padding-bottom:5px;border-bottom:1px solid var(--line-soft)}
.skill-node{display:flex;gap:7px;padding:7px;border:1px solid var(--line-soft);background:rgba(0,0,0,.2);border-radius:3px;margin-bottom:6px;text-align:left;width:100%;opacity:.55}
.skill-node.unlocked{opacity:1;border-color:rgba(125,220,154,.35);background:rgba(125,220,154,.05)}
.skill-node.available{opacity:1;border-color:var(--line);background:rgba(217,180,106,.05)}
.skill-node .sn-ico{width:24px;height:24px;flex:0 0 auto;display:flex;align-items:center;justify-content:center;border:1px solid var(--line-soft);border-radius:50%;color:var(--gold);font-size:11px}
.skill-node b{display:block;font-size:10px;color:var(--parch);line-height:1.2}.skill-node small{display:block;font-size:8px;color:var(--muted);line-height:1.3;margin-top:1px}
.skill-node .sn-cost{font-size:8px;color:var(--gold);white-space:nowrap;margin-left:auto}
.creature-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:7px}
.creature-card{border:1px solid var(--line-soft);background:rgba(255,255,255,.025);border-radius:3px;padding:7px;text-align:left;position:relative}
.creature-card:hover{border-color:var(--line)}
.creature-card.unknown{opacity:.42;filter:grayscale(1)}
.creature-card.active{border-color:var(--violet);box-shadow:0 0 14px rgba(180,140,255,.12)}
.creature-card canvas{width:54px;height:54px;display:block;margin:0 auto 3px}
.creature-card b{display:block;font-size:10px;text-align:center;line-height:1.2}
.creature-card small{display:block;font-size:8px;color:var(--muted);text-align:center;text-transform:uppercase;letter-spacing:.08em}
.creature-card .cc-badge{position:absolute;top:4px;right:5px;font-size:7px;color:var(--violet);border:1px solid rgba(180,140,255,.4);padding:0 3px;border-radius:2px}
.creature-detail{display:grid;grid-template-columns:130px 1fr;gap:12px}
.creature-detail canvas{width:130px;height:130px;background:radial-gradient(circle,rgba(180,140,255,.1),transparent 70%);border:1px solid var(--line-soft);border-radius:4px}
.creature-detail h3{margin:0 0 2px;font-family:var(--serif);font-size:18px;color:var(--gold-bright)}
.creature-detail .cd-sub{font-size:9px;letter-spacing:.1em;text-transform:uppercase;color:var(--muted);margin-bottom:7px}
.creature-detail p{font-size:11px;line-height:1.5;color:#c9d0dd;margin:6px 0}
.creature-detail .cd-ability{border-left:2px solid var(--violet);padding-left:8px;margin:7px 0;font-size:10px}
.creature-detail .cd-ability b{color:#dcc9ff;display:block;font-size:10px}
.quest-card{border:1px solid var(--line-soft);background:rgba(255,255,255,.02);border-radius:3px;padding:10px 12px;margin-bottom:7px;border-left:2px solid var(--gold)}
.quest-card.done{opacity:.55;border-left-color:var(--green)}
.quest-card h4{margin:0;font-family:var(--serif);font-size:13px;color:var(--gold-bright);letter-spacing:.05em}
.quest-card .qc-type{font-size:8px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}
.quest-card p{font-size:11px;color:#c9d0dd;line-height:1.45;margin:4px 0}
.quest-card .qc-obj{font-size:10px;color:var(--amber)}
.quest-card .qc-reward{font-size:9px;color:var(--muted);margin-top:3px}
.map-shell{display:grid;grid-template-columns:1fr 260px;gap:12px;height:100%;min-height:340px}
.zone-map{position:relative;border:1px solid var(--line-soft);background:radial-gradient(circle at 50% 40%,#182338,#080c14);border-radius:4px;overflow:hidden}
.zone-map canvas{width:100%;height:100%;display:block}
.map-legend{position:absolute;left:10px;bottom:10px;font-size:9px;color:var(--muted);background:rgba(0,0,0,.55);padding:5px 8px;border-radius:2px;line-height:1.5}
.map-side .map-row{display:flex;justify-content:space-between;align-items:center;gap:5px;padding:5px 0;border-bottom:1px solid var(--line-soft);font-size:10px}
.map-side .map-row button{font-size:9px;padding:2px 7px}
.settings-row{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:8px 0;border-bottom:1px solid var(--line-soft)}
.settings-row .sr-label{font-size:11px}.settings-row .sr-label small{display:block;font-size:9px;color:var(--muted);margin-top:1px}
.settings-row input[type=range]{width:140px;accent-color:var(--gold);background:transparent}
.settings-row select{background:rgba(0,0,0,.35);border:1px solid var(--line);color:var(--parch);padding:4px 7px;border-radius:2px;font-size:10px}
.toggle{width:40px;height:21px;border-radius:20px;border:1px solid var(--line);background:rgba(0,0,0,.4);position:relative;flex:0 0 auto}
.toggle::after{content:'';position:absolute;left:2px;top:2px;width:15px;height:15px;border-radius:50%;background:#8a93a6;transition:.18s}
.toggle.on{background:rgba(217,180,106,.25);border-color:var(--gold)}
.toggle.on::after{left:21px;background:var(--gold-bright);box-shadow:0 0 8px rgba(244,223,163,.6)}
.shop-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.shop-item{display:flex;align-items:center;gap:8px;padding:7px;border:1px solid var(--line-soft);background:rgba(255,255,255,.02);border-radius:3px;margin-bottom:5px}
.shop-item .si-glyph{width:30px;height:30px;display:flex;align-items:center;justify-content:center;border:1px solid var(--line-soft);border-radius:2px;color:var(--gold);font-size:13px;flex:0 0 auto}
.shop-item .si-info{flex:1;min-width:0}.shop-item .si-info b{display:block;font-size:10px}.shop-item .si-info small{display:block;font-size:8px;color:var(--muted)}
.shop-item .si-price{font-size:10px;color:var(--gold);white-space:nowrap}
.shop-item .si-buy{font-size:9px;padding:3px 7px;border:1px solid var(--line);border-radius:2px;color:var(--gold)}
.shop-item .si-buy:disabled{opacity:.3}
.empty-note{font-size:11px;color:var(--muted);font-style:italic;padding:20px;text-align:center}
@media (max-width:900px){
  .menu-shell{grid-template-columns:56px 1fr;height:94vh;width:98vw}
  .menu-side{padding:8px 4px}.menu-brand{font-size:0;padding-bottom:6px}.menu-brand b{font-size:0;margin:0}.menu-brand::after{content:'✦';font-size:16px}
  .tab-btn{padding:7px 4px;justify-content:center}.tab-btn span{font-size:15px;width:auto}.tab-btn b{display:none}
  .menu-side-foot{display:none}
  .menu-head{padding:8px 12px}.menu-head h2{font-size:14px}.menu-head p{display:none}
  .menu-body{padding:9px 11px}
  .cols-4{grid-template-columns:1fr 1fr}.cols-3{grid-template-columns:1fr 1fr}
  .skill-tree{grid-template-columns:1fr;gap:6px}
  .map-shell{grid-template-columns:1fr;height:auto}
  .creature-detail{grid-template-columns:100px 1fr}.creature-detail canvas{width:100px;height:100px}
  .menu-btn b{font-size:13px}.menu-btn small{display:none}
}
@media (max-width:600px){.cols-2{grid-template-columns:1fr}.item-grid{grid-template-columns:repeat(auto-fill,minmax(135px,1fr))}.stat-grid{grid-template-columns:1fr 1fr}}

/* ---------- dialogue ---------- */
.dialogue-layer{position:absolute;inset:0;z-index:50;display:flex;align-items:flex-end;justify-content:center;padding:0 3vw calc(var(--safe-b) + 2vh);pointer-events:none}
.dialogue-layer>*{pointer-events:auto}
.dialogue-letterbox{position:absolute;left:0;right:0;height:9vh;background:linear-gradient(180deg,#020407,rgba(2,4,7,.75));pointer-events:none}
.dialogue-letterbox.top{top:0}.dialogue-letterbox.bottom{bottom:0;background:linear-gradient(0deg,#020407,rgba(2,4,7,.75))}
.dialogue-panel{position:relative;width:min(1000px,94vw);min-height:150px;display:grid;grid-template-columns:150px 1fr;gap:14px;padding:14px;border-radius:5px;z-index:2;animation:dialogueIn .25s ease-out}
@keyframes dialogueIn{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
.dialogue-portrait-wrap{position:relative;align-self:start;border:1px solid var(--line);background:radial-gradient(circle at 50% 35%,rgba(217,180,106,.12),rgba(0,0,0,.5));border-radius:3px;overflow:hidden;min-height:150px}
.dialogue-portrait-wrap canvas{width:100%;height:100%;display:block}
.dialogue-portrait-wrap span{position:absolute;bottom:0;left:0;right:0;text-align:center;font-size:8px;letter-spacing:.16em;text-transform:uppercase;background:rgba(0,0,0,.65);color:var(--gold);padding:2px}
.dialogue-body{min-width:0;display:flex;flex-direction:column;justify-content:center;position:relative}
.dialogue-speaker{font-family:var(--serif);font-size:16px;letter-spacing:.12em;color:var(--gold-bright);margin-bottom:3px}
.dialogue-text{font-size:clamp(13px,1.35vw,16px);line-height:1.55;color:#e9e4d7;min-height:50px;max-height:34vh;overflow-y:auto;padding-right:4px}
.dialogue-text::after{content:'▾';display:inline-block;color:var(--gold);margin-left:4px;animation:blink 1s infinite;opacity:0}
.dialogue-text.typing::after{opacity:1}
.dialogue-choices{display:flex;flex-direction:column;gap:5px;margin-top:8px}
.dialogue-choice{text-align:left;padding:7px 11px;border:1px solid var(--line-soft);border-left:2px solid var(--gold);background:rgba(255,255,255,.03);border-radius:2px;font-size:12px;color:#d9d2c1}
.dialogue-choice:hover{background:rgba(217,180,106,.12);border-color:var(--line);color:var(--gold-bright)}
.dialogue-choice small{display:block;font-size:9px;color:var(--muted);margin-top:1px}
.dialogue-next{align-self:flex-end;margin-top:7px;padding:4px 9px;font-size:9px;letter-spacing:.08em;text-transform:uppercase;color:var(--gold);border:1px solid var(--line-soft);border-radius:2px;background:rgba(0,0,0,.2)}
.dialogue-next kbd{margin-left:4px;font-size:8px}
@keyframes blink{50%{opacity:0}}
@media (max-width:900px){
  .dialogue-layer{padding:0 8px calc(var(--safe-b) + 6px)}
  .dialogue-panel{grid-template-columns:88px 1fr;gap:9px;padding:8px;min-height:112px;width:100%}
  .dialogue-portrait-wrap{min-height:100px}
  .dialogue-speaker{font-size:12px}.dialogue-text{font-size:11px;min-height:34px;max-height:30vh;line-height:1.4}
  .dialogue-choice{font-size:10px;padding:5px 8px}.dialogue-next{font-size:8px}
  .dialogue-letterbox{height:5vh}
}
@media (max-height:480px){.dialogue-panel{min-height:96px}.dialogue-text{max-height:26vh}.dialogue-portrait-wrap{min-height:88px}}

/* ---------- cinematic ---------- */
.cinematic-layer{position:absolute;inset:0;z-index:55;background:#03050a;overflow:hidden}
#cine-canvas{position:absolute;inset:0;width:100%;height:100%}
.cine-vignette{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 40%,transparent 30%,rgba(0,0,0,.7) 100%);pointer-events:none}
.cine-letterbox{position:absolute;left:0;right:0;height:7vh;background:#000;z-index:2}
.cine-letterbox.top{top:0}.cine-letterbox.bottom{bottom:0}
.cine-content{position:absolute;left:50%;bottom:calc(7vh + 4vh);transform:translateX(-50%);width:min(860px,86vw);text-align:center;z-index:3;text-shadow:0 2px 20px #000}
.cine-eyebrow{font-size:9px;margin-bottom:5px;color:rgba(217,180,106,.8)}
.cine-content h2{font-family:var(--serif);font-size:clamp(22px,3.4vw,40px);font-weight:600;letter-spacing:.08em;margin:0 0 8px;color:var(--gold-bright);text-shadow:0 4px 30px rgba(0,0,0,.9)}
.cine-content p{font-size:clamp(12px,1.5vw,16px);line-height:1.7;color:#e4dfd1;margin:0 auto;max-width:720px;min-height:3.4em}
.cine-controls{display:flex;justify-content:center;gap:10px;margin-top:16px}
.cine-dots{display:flex;justify-content:center;gap:5px;margin-top:12px}
.cine-dots i{width:18px;height:2px;background:rgba(255,255,255,.18)}.cine-dots i.on{background:var(--gold)}
.cine-content .menu-btn.primary{background:linear-gradient(90deg,rgba(64,52,29,.8),rgba(20,24,34,.9))}
@media (max-height:480px){.cine-content{bottom:calc(7vh + 8px)}.cine-content h2{font-size:18px;margin-bottom:3px}.cine-content p{font-size:11px;line-height:1.5;min-height:2.8em}.cine-controls{margin-top:6px}.cine-dots{margin-top:5px}}

/* ---------- toasts / banner / fade ---------- */
.toasts{position:absolute;right:calc(var(--safe-r) + 16px);bottom:calc(var(--safe-b) + 16px);z-index:70;display:flex;flex-direction:column;gap:6px;align-items:flex-end;pointer-events:none;max-width:min(360px,70vw)}
.toast{display:flex;align-items:center;gap:8px;padding:8px 12px;background:rgba(8,13,22,.94);border:1px solid var(--line);border-left:2px solid var(--gold);border-radius:3px;font-size:11px;color:var(--parch);box-shadow:0 8px 30px rgba(0,0,0,.5);animation:toastIn .25s ease-out;transition:opacity .3s,transform .3s}
.toast.out{opacity:0;transform:translateX(20px)}
.toast .tg{color:var(--gold);font-size:14px}
.toast.good{border-left-color:var(--green)}.toast.good .tg{color:var(--green)}
.toast.bad{border-left-color:var(--red)}.toast.bad .tg{color:var(--red)}
.toast.rare{border-left-color:var(--violet)}.toast.rare .tg{color:var(--violet)}
@keyframes toastIn{from{opacity:0;transform:translateX(24px)}to{opacity:1;transform:none}}
.banner{position:absolute;left:50%;top:22%;transform:translateX(-50%);z-index:65;text-align:center;pointer-events:none;width:min(720px,90vw);animation:bannerIn .5s ease-out}
.banner span{font-family:var(--serif);font-size:9px;letter-spacing:.4em;color:var(--gold);text-transform:uppercase}
.banner h3{font-family:var(--serif);font-size:clamp(20px,3.5vw,38px);font-weight:600;letter-spacing:.12em;margin:5px 0;color:var(--gold-bright);text-shadow:0 3px 30px #000,0 0 40px rgba(217,180,106,.3)}
.banner p{font-size:12px;color:#d5d0c2;margin:0;text-shadow:0 2px 10px #000}
@keyframes bannerIn{from{opacity:0;transform:translate(-50%,-10px)}to{opacity:1;transform:translate(-50%,0)}}
.fade{position:absolute;inset:0;z-index:80;background:#020407;opacity:0;pointer-events:none;transition:opacity .5s}
.fade.on{opacity:1;pointer-events:auto}
.fade .fade-text{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font-family:var(--serif);letter-spacing:.3em;font-size:12px;color:var(--gold);text-align:center;line-height:2}
.rotate-hint{position:absolute;inset:0;z-index:150;background:radial-gradient(circle at 50% 40%,#14213a,#04060b 75%);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:20px}
.rotate-hint .rotate-icon{font-size:48px;color:var(--gold);animation:rotateHint 2s ease-in-out infinite}
.rotate-hint h3{font-family:var(--serif);font-size:18px;letter-spacing:.1em;margin:8px 0 2px;color:var(--gold-bright)}
.rotate-hint p{font-size:11px;color:var(--muted);margin:0}
@keyframes rotateHint{0%,100%{transform:rotate(0)}50%{transform:rotate(90deg)}}

/* credits */
.credits-body{font-size:12px;line-height:1.65;color:#cbd2df;max-width:760px;margin:0 auto}
.credits-body h3{font-family:var(--serif);font-size:15px;letter-spacing:.12em;color:var(--gold-bright);margin:16px 0 5px}
.credits-body p{margin:0 0 8px}
.credits-body .fine{font-size:10px;color:var(--muted);font-style:italic}
.credits-body blockquote{border-left:2px solid var(--gold);margin:10px 0;padding:5px 14px;font-style:italic;color:#dcd6c6;font-size:13px}

// ============================================================
// LA ESPADA CELESTIAL — núcleo técnico
// Utilidades, entrada, audio procedural y guardado local.
// ============================================================

export const TAU = Math.PI * 2;
export const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
export const lerp = (a, b, t) => a + (b - a) * t;
export const invLerp = (a, b, v) => (v - a) / (b - a);
export const smoothstep = (a, b, v) => { const t = clamp(invLerp(a, b, v), 0, 1); return t * t * (3 - 2 * t); };
export const dist = (ax, ay, bx, by) => Math.hypot(bx - ax, by - ay);
export const dist2 = (ax, ay, bx, by) => { const dx = bx - ax, dy = by - ay; return dx * dx + dy * dy; };
export const len = (x, y) => Math.hypot(x, y);
export const norm = (x, y) => { const l = Math.hypot(x, y) || 1; return { x: x / l, y: y / l }; };
export const angleTo = (ax, ay, bx, by) => Math.atan2(by - ay, bx - ax);
export const angleDiff = (a, b) => { let d = (b - a) % TAU; if (d > Math.PI) d -= TAU; if (d < -Math.PI) d += TAU; return d; };
export const angleLerp = (a, b, t) => a + angleDiff(a, b) * t;
export const choose = (arr, rng = Math.random) => arr[Math.floor(rng() * arr.length)];
export const chance = (p, rng = Math.random) => rng() < p;
export const uid = (() => { let n = 0; return (p = 'id') => `${p}_${++n}`; })();
export const fmt = n => Math.round(n).toLocaleString('es-ES');
export const pad = (n, l = 2) => String(n).padStart(l, '0');

export function hashString(str) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}

export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function seededFor(...parts) {
  return mulberry32(hashString(parts.join('|')));
}

export function shuffle(arr, rng = Math.random) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}

export function pointInRect(x, y, r) { return x >= r.x && x <= r.x + r.w && y >= r.y && y <= r.y + r.h; }
export function pointInCircle(x, y, c) { return dist2(x, y, c.x, c.y) <= (c.r || 0) ** 2; }
export function rectsOverlap(a, b) { return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y; }

export function circleRectOverlap(cx, cy, cr, rx, ry, rw, rh) {
  const nx = clamp(cx, rx, rx + rw), ny = clamp(cy, ry, ry + rh);
  return dist2(cx, cy, nx, ny) < cr * cr;
}

export function easeOutCubic(t) { return 1 - (1 - t) ** 3; }
export function easeInCubic(t) { return t * t * t; }
export function easeOutBack(t) { const c = 1.70158; return 1 + (c + 1) * (t - 1) ** 3 + c * (t - 1) ** 2; }

export function formatPlaytime(sec) {
  sec = Math.max(0, Math.floor(sec));
  const h = Math.floor(sec / 3600), m = Math.floor((sec % 3600) / 60);
  return h > 0 ? `${h}h ${pad(m)}m` : `${m}m`;
}

