          { text: 'Compra dos y te regalo una historia. La historia es mentira, pero el descuento no.' },
          { text: 'Mirar es gratis. Recordar, no.' },
        ],
      };
    },
  },

  archivista: {
    name: 'Archivista', role: 'Guardiana del Templo de Cristal', portrait: 'archivista',
