  _noiseTexture() {
    if (this._noise) return this._noise;
    const c = document.createElement('canvas'); c.width = c.height = 256;
    const ctx = c.getContext('2d'); const img = ctx.createImageData(256, 256);
    for (let i = 0; i < img.data.length; i += 4) {
