    const sway = Math.sin(time * 1.5 + d.seed) * 2;
    switch (d.type) {
      case 'grass': {
        ctx.save(); ctx.strokeStyle = zone.theme === 'pass' || zone.theme === 'city' || zone.theme === 'fortress' ? 'rgba(120,90,60,.5)' : 'rgba(60,120,50,.5)';
