182: export class AudioEngine {
183:   constructor() {
184:     this.ctx = null;
185:     this.master = null;
186:     this.musicBus = null;
187:     this.sfxBus = null;
188:     this.reverb = null;
189:     this.mode = 'title';
190:     this.volume = { master: 0.75, music: 0.55, sfx: 0.7 };
191:     this.muted = false;
192:     this.step = 0;
193:     this.nextTime = 0;
194:     this.timer = 0;
195:     this.ready = false;
196:     this.battle = false;
197:     this._seed = 1;
198:   }
199:   init() {
200:     if (this.ctx) { this.resume(); return; }
201:     const AC = window.AudioContext || window.webkitAudioContext;
202:     if (!AC) return;
203:     try {
204:       this.ctx = new AC();
205:       this.master = this.ctx.createGain();
206:       this.master.gain.value = this.volume.master;
207:       this.master.connect(this.ctx.destination);
208:       this.musicBus = this.ctx.createGain();
209:       this.musicBus.gain.value = this.volume.music;
210:       this.musicBus.connect(this.master);
211:       this.sfxBus = this.ctx.createGain();
212:       this.sfxBus.gain.value = this.volume.sfx;
213:       this.sfxBus.connect(this.master);
214:       const len = this.ctx.sampleRate * 2.4;
215:       const imp = this.ctx.createBuffer(2, len, this.ctx.sampleRate);
216:       for (let ch = 0; ch < 2; ch++) {
217:         const d = imp.getChannelData(ch);
218:         for (let i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / len) ** 2.6;
219:       }
220:       const conv = this.ctx.createConvolver(); conv.buffer = imp;
221:       this.reverb = this.ctx.createGain(); this.reverb.gain.value = 0.28;
222:       conv.connect(this.reverb); this.reverb.connect(this.master);
223:       this.musicReverb = this.ctx.createGain(); this.musicReverb.gain.value = 0.42;
224:       this.musicReverb.connect(conv);
225:       this.ready = true;
226:       this.nextTime = this.ctx.currentTime + 0.1;
227:       this.step = 0;
228:     } catch (e) { console.warn('Audio no disponible', e); }
229:   }
230:   resume() { if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume().catch(() => {}); }
231:   setVolume(kind, v) {
232:     this.volume[kind] = clamp(v, 0, 1);
233:     if (!this.ctx) return;
234:     if (kind === 'master') this.master.gain.value = this.muted ? 0 : this.volume.master;
235:     if (kind === 'music') this.musicBus.gain.value = this.volume.music;
236:     if (kind === 'sfx') this.sfxBus.gain.value = this.volume.sfx;
237:   }
238:   setMuted(m) {
239:     this.muted = m;
240:     if (this.master) this.master.gain.value = m ? 0 : this.volume.master;
241:   }
242:   setMode(mode, battle = false) {
243:     if (this.mode === mode && this.battle === battle) return;
244:     this.mode = mode; this.battle = battle;
245:     this.step = 0;
246:     if (this.ctx) this.nextTime = Math.max(this.nextTime, this.ctx.currentTime + 0.05);
247:   }
248:   update() {
249:     if (!this.ready || !this.ctx || this.ctx.state !== 'running') return;
250:     const lookahead = 0.25;
251:     const mood = MOODS[this.mode] || MOODS.title;
252:     const battleMood = this.battle ? MOODS.battle : null;
253:     const spb = 60 / (this.battle ? Math.max(mood.tempo, 100) : mood.tempo);
254:     const stepDur = spb / 4;
255:     while (this.nextTime < this.ctx.currentTime + lookahead) {
256:       this._scheduleStep(this.step, this.nextTime, mood, battleMood);
257:       this.nextTime += stepDur;
258:       this.step++;
259:     }
260:   }
261:   _scheduleStep(step, t, mood, battleMood) {
262:     const bar = Math.floor(step / 16), beat = step % 16;
263:     const root = mood.root;
264:     const rng = mulberry32(hashString(this.mode + ':' + bar + ':' + (this.battle ? 'b' : 'c')));
265:     const scale = mood.scale;
266:     const chord = mood.chords[bar % mood.chords.length];
267:     const freq = n => root * Math.pow(2, n / 12);
268:     // Pad: long chord at each bar
269:     if (beat === 0) {
270:       chord.forEach((n, i) => this._note(freq(n), t, (60 / mood.tempo) * 4.1, mood.pad, 0.026, this.musicBus, 900 + i * 120, this.musicReverb));
271:       if (this.battle) this._note(freq(chord[0] - 12), t, (60 / mood.tempo) * 3.8, 'sawtooth', 0.035, this.musicBus, 280);
272:     }
273:     // Bass
274:     if (beat % 4 === 0) {
275:       this._note(freq(chord[0] - 24), t, 0.5, 'triangle', this.battle ? 0.09 : 0.055, this.musicBus, 220);
276:     }
277:     // Arpeggio
278:     if (beat % 2 === 0 && (beat % 8 !== 0 || rng() < 0.6)) {
279:       const idx = [0, 1, 2, 1, 0, 2, 1, 2][(step / 2 | 0) % 8];
280:       const octave = rng() < 0.22 ? 12 : 0;
281:       const n = chord[idx % chord.length] + octave + (rng() < 0.12 ? 12 : 0);
282:       this._note(freq(n + 12), t, 0.32, mood.arp, this.battle ? 0.028 : 0.035, this.musicBus, 2400, this.musicReverb);
283:     }
284:     // Melody
285:     if (beat % 4 === 2 && rng() < (this.battle ? 0.55 : 0.4)) {
286:       const n = choose(scale, rng) + (rng() < 0.5 ? 12 : 0);
287:       this._note(freq(n + 12), t, 0.6, 'sine', 0.028, this.musicBus, 3200, this.musicReverb);
288:     }
289:     // Percussion
290:     const intensity = this.battle ? 1 : (mood.drums || 0.3);
291:     if (intensity > 0.2) {
292:       if (beat === 0 || beat === 8 || (this.battle && beat === 10)) this._drum(t, 0.22 * intensity, 70);
293:       if (beat === 4 || beat === 12) this._drum(t, 0.12 * intensity, 120);
294:       if (this.battle && beat % 2 === 1) this._hat(t, 0.018 * intensity);
295:       if (this.battle && beat % 8 === 6) this._drum(t, 0.16, 55);
296:     }
297:     // Shimmer
298:     if (!this.battle && beat === 0 && rng() < 0.55) {
299:       this._note(freq(choose(scale, rng) + 24), t + 0.2, 1.4, 'sine', 0.014, this.musicBus, 5000, this.musicReverb);
300:     }
301:   }
302:   _note(freq, time, dur, type, gain, dest, cutoff = 2200, send = null) {
303:     if (!this.ctx) return;
304:     const o = this.ctx.createOscillator();
305:     const g = this.ctx.createGain();
306:     const f = this.ctx.createBiquadFilter();
307:     o.type = type; o.frequency.value = freq;
308:     f.type = 'lowpass'; f.frequency.value = cutoff; f.Q.value = 0.7;
309:     g.gain.setValueAtTime(0.0001, time);
310:     g.gain.linearRampToValueAtTime(gain, time + 0.03);
311:     g.gain.exponentialRampToValueAtTime(0.0001, time + dur);
312:     o.connect(f); f.connect(g); g.connect(dest);
313:     if (send) { const s = this.ctx.createGain(); s.gain.value = 0.5; g.connect(s); s.connect(send); }
314:     o.start(time); o.stop(time + dur + 0.05);
315:   }
316:   _drum(time, gain, freq) {
317:     if (!this.ctx) return;
318:     const o = this.ctx.createOscillator(); const g = this.ctx.createGain();
319:     o.type = 'sine'; o.frequency.setValueAtTime(freq * 2.2, time); o.frequency.exponentialRampToValueAtTime(freq * 0.7, time + 0.18);
320:     g.gain.setValueAtTime(gain, time); g.gain.exponentialRampToValueAtTime(0.0001, time + 0.25);
321:     o.connect(g); g.connect(this.musicBus); o.start(time); o.stop(time + 0.3);
322:   }
323:   _hat(time, gain) {
324:     if (!this.ctx) return;
325:     const src = this.ctx.createBufferSource();
326:     const b = this.ctx.createBuffer(1, this.ctx.sampleRate * 0.05, this.ctx.sampleRate);
327:     const d = b.getChannelData(0);
328:     for (let i = 0; i < d.length; i++) d[i] = (Math.random() * 2 - 1) * (1 - i / d.length);
329:     src.buffer = b;
330:     const f = this.ctx.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 7000;
331:     const g = this.ctx.createGain(); g.gain.setValueAtTime(gain, time); g.gain.exponentialRampToValueAtTime(0.0001, time + 0.04);
332:     src.connect(f); f.connect(g); g.connect(this.musicBus); src.start(time);
333:   }
334:   sfx(name) {
