68:     this.maxHP = Math.round(70 + this.attrs.vida * 9 + this.level * 8 + sum('hp') + (sk.hp || 0));
69:     this.maxMP = Math.round(25 + this.attrs.mana * 7 + this.level * 2 + sum('mp'));
70:     this.maxStamina = Math.round(70 + this.attrs.resistencia * 5 + this.level * 2 + sum('stam') + (sk.stam || 0));
71:     this.attack = Math.round(5 + this.attrs.fuerza * 1.6 + this.level * 0.9 + sum('atk'));
72:     this.defense = Math.round((2 + this.attrs.defensa * 1.1 + this.level * 0.4 + sum('def')) * (1 + (sk.defPct || 0)));
73:     this.speed = 150 + this.attrs.velocidad * 3.2 + sum('spd');
74:     this.spellPower = 4 + this.attrs.inteligencia * 2.2 + this.level * 0.7;
75:     this.crit = 5 + this.attrs.suerte * 1.0 + sum('crit') + (sk.crit || 0);
76:     this.critDmg = 1.6 + (sk.critDmg || 0);
77:     this.luck = this.attrs.suerte * 1.5 + sum('luck') + (sk.luck || 0);
78:     this.captureBonus = (sum('capture') / 100) + (sk.capture || 0) + this.attrs.suerte * 0.004;
79:     this.allDmg = 1 + (sum('allDmg') || 0) / 100 + (sk.allDmg || 0);
80:     this.fireBonus = (sum('fire') || 0) / 100;
81:     this.fireRes = clamp((sum('fireRes') || 0) / 100, 0, 0.75);
82:     this.reveal = (sk.reveal || 0) + (sum('reveal') || 0);
83:     this.weaponElement = items.find(i => i.type === 'weapon')?.element || 'luz';
84:     this.weaponGlow = items.find(i => i.type === 'weapon')?.glow || '#ffe9a8';
85:     this.weaponColor = items.find(i => i.type === 'weapon')?.color || '#e8e2cf';
86:     this.armorColor = items.find(i => i.type === 'armor')?.color;
87:     this.armorTrim = items.find(i => i.type === 'armor')?.trim;
88:     this.helmetColor = items.find(i => i.type === 'helmet')?.color;
89:     this.helmetId = eq.helmet || null;
90:     this.weaponId = eq.weapon || null;
91:     this.hp = Math.min(this.hp ?? this.maxHP, this.maxHP);
92:     this.mp = Math.min(this.mp ?? this.maxMP, this.maxMP);
93:     this.stamina = Math.min(this.stamina ?? this.maxStamina, this.maxStamina);
94:   }
95: 
96:   get hpPct() { return this.maxHP ? this.hp / this.maxHP : 0; }
97:   get mpPct() { return this.maxMP ? this.mp / this.maxMP : 0; }
98:   get staminaPct() { return this.maxStamina ? this.stamina / this.maxStamina : 0; }
99:   get busy() { return this.state === 'attack' || this.state === 'heavy' || this.state === 'dodge' || this.state === 'cast' || this.state === 'hurt' || this.state === 'dead'; }
100:   get moving() { return Math.abs(this.vx) + Math.abs(this.vy) > 8; }
101: 
102:   update(dt, game) {
103:     this.stateTime += dt;
104:     this.walkPhase += dt * (this.moving ? 9 : 2.2);
105:     this.hurtFlash = Math.max(0, this.hurtFlash - dt * 4);
106:     this.invuln = Math.max(0, this.invuln - dt);
107:     this.spellCooldowns = this.spellCooldowns.map(c => Math.max(0, c - dt));
108:     this.comboReset = Math.max(0, this.comboReset - dt);
109:     this.shieldTimer = Math.max(0, this.shieldTimer - dt);
110:     this.hitstop = Math.max(0, this.hitstop - dt);
111:     if (this.dead) { this.deathTime += dt; return; }
112:     if (this.hitstop > 0) return;
113: 
114:     // estados
115:     for (const k of Object.keys(this.statuses)) this.statuses[k] = Math.max(0, this.statuses[k] - dt);
116:     if (this.statuses.burn > 0 && Math.random() < dt * 3) {
117:       this.hp -= 1 + this.level * 0.35;
118:       game.addText(this.x, this.y - 48, '−' + Math.round(1 + this.level * 0.35), '#ff8a5c', 12);
119:       if (this.hp <= 0) this.die(game);
120:     }
121:     if (this.statuses.poison > 0 && Math.random() < dt * 2.5) {
122:       this.hp -= 1;
123:       game.addText(this.x, this.y - 42, '−1', '#9fd67a', 11);
124:     }
125: 
126:     // regeneración
127:     this.staminaDelay = Math.max(0, this.staminaDelay - dt);
128:     this.manaDelay = Math.max(0, this.manaDelay - dt);
129:     const stamRegen = (18 + this.attrs.resistencia * 0.8) * (game.hasSkill('ancla') ? 1.5 : 1);
130:     if (this.state !== 'dodge' && this.state !== 'attack' && this.state !== 'heavy') {
131:       this.stamina = Math.min(this.maxStamina, this.stamina + stamRegen * dt);
132:     }
133:     if (this.manaDelay <= 0) this.mp = Math.min(this.maxMP, this.mp + (3.5 + this.attrs.inteligencia * 0.08) * dt);
134:     const threat = game.enemies?.some(e => !e.dead && e.aggro && dist2(e.x, e.y, this.x, this.y) < 500 ** 2);
135:     if (!threat) this.hp = Math.min(this.maxHP, this.hp + (1.2 + this.attrs.vida * 0.02) * dt);
136:     if (this.statuses.shield > 0) this.statuses.shield = Math.max(0, this.statuses.shield - dt);
137: 
138:     if (game.state !== 'playing' || game.dialogueOpen || game.ui.blockingInput) { this.vx = this.vy = 0; return; }
139: 
140:     // dirección de apuntado
141:     const aim = game.getAimAngle(this);
142:     if (!this.busy) this.facing = aim;
143: 
144:     // acciones
145:     const input = game.input;
146:     if (this.state === 'idle' || this.state === 'move' || this.state === 'block') {
147:       if (input.isDown('block') && this.stamina > 1) {
148:         if (this.state !== 'block') { this.state = 'block'; this.stateTime = 0; this.blockTime = 0; }
149:         this.blocking = true;
150:         this.blockTime += dt;
151:       } else {
152:         if (this.state === 'block') { this.state = 'idle'; this.blocking = false; }
153:       }
154:       if (input.consume('dodge')) this.tryDodge(game);
155:       else if (input.consume('heavy')) this.tryHeavy(game, aim);
156:       else if (input.isDown('attack')) this.tryAttack(game, aim);
157:       else if (input.consume('spell1')) game.castSpell(0);
158:       else if (input.consume('spell2')) game.castSpell(1);
159:       else if (input.consume('spell3')) game.castSpell(2);
160:       else if (input.consume('potion')) game.usePotion();
161:       else if (input.consume('creature')) game.useCreatureSkill();
162:       else if (input.consume('capture')) game.tryCaptureNearest();
163:     }
164: 
165:     // movimiento
166:     if (!this.busy && this.state !== 'block') {
167:       const mx = input.moveX, my = input.moveY;
168:       const m = Math.hypot(mx, my);
169:       if (m > 0.15) {
170:         const n = norm(mx, my);
171:         const sp = this.speed * clamp(m, 0, 1) * (this.statuses.slow > 0 ? 0.6 : 1);
172:         this.vx = n.x * sp; this.vy = n.y * sp;
173:         if (this.state !== 'move') { this.state = 'move'; this.stateTime = 0; }
174:       } else {
175:         this.vx *= 0.7; this.vy *= 0.7;
176:         if (this.state === 'move') this.state = 'idle';
177:       }
178:     } else if (this.state === 'block') {
179:       const mx = input.moveX, my = input.moveY;
180:       const m = Math.hypot(mx, my);
181:       if (m > 0.15) {
182:         const n = norm(mx, my);
183:         this.vx = n.x * this.speed * 0.38; this.vy = n.y * this.speed * 0.38;
184:       } else { this.vx *= 0.6; this.vy *= 0.6; }
185:     } else {
186:       this.vx *= 0.85; this.vy *= 0.85;
187:     }
188: 
189:     // estados con temporizador
190:     if (this.state === 'attack') this.updateAttack(dt, game);
191:     else if (this.state === 'heavy') this.updateHeavy(dt, game);
192:     else if (this.state === 'dodge') this.updateDodge(dt, game);
193:     else if (this.state === 'cast') this.updateCast(dt, game);
194:     else if (this.state === 'hurt' && this.stateTime > 0.24) { this.state = 'idle'; this.stateTime = 0; }
195: 
196:     // aplicar movimiento
197:     if (Math.abs(this.vx) + Math.abs(this.vy) > 0.5) {
198:       game.moveEntity(this, this.vx * dt, this.vy * dt);
199:     }
200:     this.bob = Math.sin(this.walkPhase) * (this.moving ? 1.4 : 0.5);
201:   }
202: 
203:   tryAttack(game, aim) {
204:     if (this.state === 'attack') {
205:       if (this.attackTime > 0.1) this.attackQueued = true;
206:       return;
207:     }
208:     if (this.stamina < 6) { game.toast('Sin resistencia', 'bad'); return; }
209:     this.state = 'attack';
210:     this.stateTime = 0;
211:     this.attackTime = 0;
212:     this.attackIndex = this.comboReset > 0 ? (this.attackIndex % 3) + 1 : 1;
213:     this.comboReset = 0.85;
214:     this.hasHit = false;
215:     this.attackQueued = false;
216:     this.facing = aim;
217:     this.stamina -= 7;
218:     this.staminaDelay = 0.35;
219:     game.audio.sfx('slash');
220:   }
221: 
222:   updateAttack(dt, game) {
223:     this.attackTime += dt;
224:     if (!this.hasHit && this.attackTime >= 0.12) {
225:       this.hasHit = true;
226:       game.playerMeleeHit(this, false);
227:     }
228:     if (this.attackTime >= 0.34) {
229:       if (this.attackQueued && this.stamina >= 6) {
230:         this.attackQueued = false;
231:         this.attackIndex = (this.attackIndex % 3) + 1;
232:         this.attackTime = 0;
233:         this.hasHit = false;
234:         this.stateTime = 0;
235:         this.stamina -= 6;
236:         this.facing = game.getAimAngle(this);
237:         game.audio.sfx('slash');
238:       } else {
239:         this.state = 'idle'; this.stateTime = 0; this.attackIndex = 0;
240:       }
241:     }
242:   }
243: 
244:   tryHeavy(game, aim) {
245:     if (this.stamina < 18) { game.toast('Sin resistencia', 'bad'); return; }
246:     this.state = 'heavy'; this.stateTime = 0; this.attackTime = 0; this.hasHit = false;
247:     this.facing = aim; this.stamina -= 18; this.staminaDelay = 0.5;
248:     game.audio.sfx('slash');
249:   }
250:   updateHeavy(dt, game) {
251:     this.attackTime += dt;
252:     if (!this.hasHit && this.attackTime >= 0.32) { this.hasHit = true; game.playerMeleeHit(this, true); }
253:     if (this.attackTime >= 0.62) { this.state = 'idle'; this.stateTime = 0; }
254:   }
255: 
256:   tryDodge(game) {
257:     const cost = 16 - (game.hasSkill('paso_umbrio') ? 3 : 0);
258:     if (this.stamina < cost) { game.toast('Sin resistencia', 'bad'); return; }
259:     const mx = game.input.moveX, my = game.input.moveY;
260:     const dir = Math.hypot(mx, my) > 0.2 ? norm(mx, my) : { x: Math.cos(this.facing), y: Math.sin(this.facing) };
261:     this.state = 'dodge'; this.stateTime = 0; this.dodgeTime = 0; this.dodgeDir = dir;
262:     this.invuln = 0.27 + (game.hasSkill('paso_umbrio') ? 0.1 : 0);
263:     this.stamina -= cost; this.staminaDelay = 0.5;
264:     game.audio.sfx('dodge');
265:     game.spawnParticles(this.x, this.y, 8, '#c7f0e0', 60, 0.35, 2);
266:   }
267:   updateDodge(dt, game) {
268:     this.dodgeTime += dt;
269:     const t = clamp(this.dodgeTime / 0.34, 0, 1);
270:     const sp = 500 * (1 - t * 0.55);
271:     this.vx = this.dodgeDir.x * sp;
272:     this.vy = this.dodgeDir.y * sp;
273:     if (Math.random() < 0.7) game.spawnParticles(this.x, this.y, 1, '#e8fbff', 18, 0.3, 1.4);
274:     if (this.dodgeTime >= 0.34) {
275:       this.state = 'idle'; this.stateTime = 0;
276:       if (game.hasSkill('segundo_aliento') && game.enemies?.some(e => !e.dead && e.aggro)) {
277:         this.hp = Math.min(this.maxHP, this.hp + this.maxHP * 0.04);
278:         game.addText(this.x, this.y - 60, '+4%', '#7ddc9a', 12);
279:       }
280:     }
281:   }
282: 
283:   startCast(game, index, aim) {
284:     this.state = 'cast'; this.stateTime = 0; this.castTime = 0; this.castIndex = index; this.castAim = aim;
285:     this.facing = aim;
286:   }
287:   updateCast(dt, game) {
288:     this.castTime += dt;
289:     if (this.castTime >= 0.24 && this.castIndex >= 0) {
290:       const idx = this.castIndex; this.castIndex = -1;
291:       game.executeSpell(idx, this.castAim);
292:     }
293:     if (this.castTime >= 0.5) { this.state = 'idle'; this.stateTime = 0; }
294:   }
295: 
296:   takeDamage(amount, game, opts = {}) {
297:     if (this.dead || this.invuln > 0) return 0;
298:     if (this.statuses.shield > 0) {
299:       const absorbed = Math.min(amount, this.statuses.shield);
300:       this.statuses.shield -= absorbed; amount -= absorbed;
301:       game.addText(this.x, this.y - 50, 'ESCUDO', '#9fe8ff', 11);
302:     }
303:     const def = this.defense * 0.55;
304:     let dmg = amount * (100 / (100 + def));
305:     if (this.statuses.weaken > 0) dmg *= 1.15;
306:     if (opts.element === 'fuego') dmg *= (1 - this.fireRes);
307:     dmg = Math.max(1, Math.round(dmg));
308:     this.hp -= dmg;
309:     this.hurtFlash = 1;
310:     this.invuln = opts.invuln ?? 0.45;
311:     this.state = 'hurt'; this.stateTime = 0; this.vx = 0; this.vy = 0;
312:     game.addText(this.x, this.y - 52, '−' + dmg, '#ff8a72', 15);
313:     game.audio.sfx('hurt');
314:     game.shake(4, 0.18);
315:     game.spawnParticles(this.x, this.y - 20, 7, '#e25a4f', 90, 0.4, 2);
316:     if (opts.knockback) {
317:       const n = norm(opts.knockback.x, opts.knockback.y);
318:       game.moveEntity(this, n.x * 24, n.y * 24);
319:     }
320:     if (this.hp <= 0) this.die(game);
321:     return dmg;
322:   }
323: 
324:   heal(amount, game, silent = false) {
325:     const before = this.hp;
326:     this.hp = Math.min(this.maxHP, this.hp + amount);
327:     const healed = Math.round(this.hp - before);
328:     if (healed > 0 && !silent) game.addText(this.x, this.y - 52, '+' + healed, '#7ddc9a', 14);
329:     return healed;
330:   }
331:   die(game) {
332:     if (this.dead) return;
333:     this.dead = true; this.hp = 0; this.state = 'dead'; this.deathTime = 0;
334:     game.onPlayerDeath();
335:   }
336: }
