338: // ============================================================
339: // ENEMIGOS
340: // ============================================================
341: export class Enemy {
342:   constructor(game, defId, x, y, opts = {}) {
343:     this.game = game;
344:     this.def = ENEMIES[defId];
345:     if (!this.def) throw new Error('Enemigo desconocido: ' + defId);
346:     this.id = defId;
347:     this.name = this.def.name;
348:     this.x = x; this.y = y;
349:     this.spawnX = x; this.spawnY = y;
350:     this.level = opts.level || game.zone?.level || 1;
351:     this.elite = !!opts.elite;
352:     this.boss = this.def.tier === 'boss';
353:     this.r = this.def.radius || 18;
354:     this.scale = this.boss ? 1 : (this.elite ? 1.18 : 1);
355:     const lvlMul = 1 + 0.28 * (this.level - 1);
356:     const eliteMul = this.elite ? 1.7 : 1;
357:     this.maxHP = Math.round(this.def.hp * lvlMul * eliteMul);
358:     this.hp = this.maxHP;
359:     this.atk = this.def.atk * (1 + 0.17 * (this.level - 1)) * (this.elite ? 1.3 : 1);
360:     this.defense = this.def.def * (1 + 0.12 * (this.level - 1)) * (this.elite ? 1.25 : 1);
361:     this.speed = this.def.speed * (this.elite ? 1.1 : 1);
362:     this.poise = this.maxPoise = this.def.poise * (this.elite ? 1.4 : 1);
363:     this.xp = Math.round(this.def.xp * (1 + 0.15 * (this.level - 1)) * (this.elite ? 1.8 : 1));
364:     this.gold = Math.round(this.def.gold * (1 + 0.1 * (this.level - 1)) * (this.elite ? 1.8 : 1));
365:     this.aggro = false;
366:     this.awake = !this.boss;
367:     this.state = 'idle';
368:     this.stateTime = 0;
369:     this.attackCooldown = 0.6 + Math.random() * 0.8;
370:     this.windup = 0;
371:     this.windupMax = 0;
372:     this.pattern = null;
373:     this.telegraph = null;
374:     this.stagger = 0;
375:     this.dead = false;
376:     this.deathTime = 0;
377:     this.hitFlash = 0;
378:     this.facing = Math.random() * TAU;
379:     this.patrolAngle = Math.random() * TAU;
380:     this.patrolTimer = 0;
381:     this.phase = 1;
382:     this.phaseAnnounced = 1;
383:     this.statuses = { burn: 0, poison: 0, slow: 0, weaken: 0, mark: 0 };
384:     this.statusPower = { burn: 0, poison: 0 };
385:     this.animTime = Math.random() * 10;
386:     this.hover = Math.random() * TAU;
387:     this.capturable = this.def.capturable;
388:     this.captureImmune = 0;
389:     this.rage = 0;
390:     this.adds = [];
391:     this.spawnFx = 0.5;
392:   }
393: 
394:   get hpPct() { return this.hp / this.maxHP; }
395:   get canCapture() {
396:     return !this.boss && this.capturable && this.hpPct <= 0.35 && this.stagger > 0 && this.captureImmune <= 0;
397:   }
398: 
399:   update(dt, game) {
400:     this.animTime += dt;
401:     this.hitFlash = Math.max(0, this.hitFlash - dt * 4);
402:     this.captureImmune = Math.max(0, this.captureImmune - dt);
403:     this.attackCooldown = Math.max(0, this.attackCooldown - dt);
404:     this.spawnFx = Math.max(0, this.spawnFx - dt);
405:     if (this.dead) { this.deathTime += dt; return; }
406:     if (!this.awake) return;
407:     for (const k of Object.keys(this.statuses)) this.statuses[k] = Math.max(0, this.statuses[k] - dt);
408:     if (this.statuses.burn > 0 && Math.random() < dt * 4) {
409:       const dmg = Math.max(1, Math.round(this.statusPower.burn));
410:       this.hp -= dmg; game.addText(this.x, this.y - this.r - 30, '−' + dmg, '#ff8a5c', 11);
411:       if (this.hp <= 0) return this.die(game);
412:     }
413:     if (this.statuses.poison > 0 && Math.random() < dt * 3) {
414:       const dmg = Math.max(1, Math.round(this.statusPower.poison));
415:       this.hp -= dmg; game.addText(this.x, this.y - this.r - 26, '−' + dmg, '#9fd67a', 10);
416:       if (this.hp <= 0) return this.die(game);
417:     }
418:     if (this.stagger > 0) {
419:       this.stagger -= dt;
420:       this.state = 'stagger'; this.telegraph = null;
421:       if (this.stagger <= 0) { this.state = 'idle'; this.poise = this.maxPoise; }
422:       return;
423:     }
424:     if (this.state === 'hurt') {
425:       this.stateTime += dt;
426:       if (this.stateTime > 0.25) this.state = 'idle';
427:       return;
428:     }
429:     const p = game.player;
430:     if (!p || p.dead) return;
431:     const d = dist(this.x, this.y, p.x, p.y);
432:     const ang = angleTo(this.x, this.y, p.x, p.y);
433:     if (!this.aggro && d < this.def.aggro) this.aggro = true;
434:     if (!this.aggro) { this.patrol(dt, game); return; }
435:     this.facing = angleLerp(this.facing, ang, clamp(dt * 6, 0, 1));
436:     if (this.boss) return this.updateBoss(dt, game, d, ang);
437: 
438:     const slow = this.statuses.slow > 0 ? 0.55 : 1;
439:     const speed = this.speed * slow * (this.rage > 0 ? 1.2 : 1);
440: 
441:     if (this.state === 'windup') {
442:       this.windup -= dt;
443:       if (this.windup <= 0) this.executeAttack(game, ang, d);
444:       return;
445:     }
446:     if (this.state === 'dash') {
447:       this.stateTime += dt;
448:       const sp = 380 * (this.elite ? 1.15 : 1);
449:       game.moveEntity(this, Math.cos(this.facing) * sp * dt, Math.sin(this.facing) * sp * dt);
450:       if (d < this.r + p.r + 18 && this.stateTime > 0.05) {
451:         game.damagePlayer(this.atk * 1.1, { source: this, element: this.def.element, knockback: { x: Math.cos(this.facing), y: Math.sin(this.facing) } });
452:         this.state = 'recover'; this.stateTime = 0; this.attackCooldown = 1.5;
453:       }
454:       if (this.stateTime > 0.36) { this.state = 'recover'; this.stateTime = 0; }
455:       return;
456:     }
457:     if (this.state === 'recover') {
458:       this.stateTime += dt;
459:       if (this.stateTime > 0.35) this.state = 'chase';
460:       return;
461:     }
462: 
463:     const behavior = this.def.behavior;
464:     if (behavior === 'ranged') {
465:       if (d > 270) this.moveToward(p.x, p.y, speed, dt, game);
466:       else if (d < 150) this.moveToward(p.x, p.y, -speed * 0.8, dt, game);
467:       else {
468:         const strafe = ang + Math.PI / 2 * (Math.sin(this.animTime * 0.8) > 0 ? 1 : -1);
469:         this.moveToward(this.x + Math.cos(strafe) * 100, this.y + Math.sin(strafe) * 100, speed * 0.35, dt, game);
470:       }
471:       if (this.attackCooldown <= 0 && d < 380) this.startWindup(0.55, 'ranged');
472:     } else if (behavior === 'charger') {
473:       if (d > 90) this.moveToward(p.x, p.y, speed, dt, game);
474:       if (this.attackCooldown <= 0 && d < 260 && d > 50) this.startWindup(0.55, 'dash');
475:     } else if (behavior === 'flyer') {
476:       this.hover += dt * 3;
477:       const tx = p.x + Math.cos(this.hover) * 40, ty = p.y - 60 + Math.sin(this.hover * 1.3) * 30;
478:       if (d > 60) this.moveToward(tx, ty, speed, dt, game);
479:       if (this.attackCooldown <= 0 && d < 120) this.startWindup(0.4, 'melee');
480:     } else {
481:       if (d > this.def.range * 0.8) this.moveToward(p.x, p.y, speed, dt, game);
482:       if (this.attackCooldown <= 0 && d < this.def.range + 12) this.startWindup(this.elite ? 0.65 : 0.5, 'melee');
483:     }
484:     // separación
485:     for (const o of game.enemies) {
486:       if (o === this || o.dead) continue;
487:       const dd = dist2(this.x, this.y, o.x, o.y);
488:       if (dd < (this.r + o.r + 4) ** 2 && dd > 0.01) {
489:         const n = norm(this.x - o.x, this.y - o.y);
490:         this.x += n.x * 14 * dt; this.y += n.y * 14 * dt;
491:       }
492:     }
493:   }
494: 
495:   patrol(dt, game) {
496:     this.patrolTimer -= dt;
497:     if (this.patrolTimer <= 0) { this.patrolTimer = 2 + Math.random() * 3; this.patrolAngle += (Math.random() - 0.5) * 1.8; }
498:     const sp = this.speed * 0.22;
499:     const nx = this.x + Math.cos(this.patrolAngle) * sp * dt;
500:     const ny = this.y + Math.sin(this.patrolAngle) * sp * dt;
501:     if (dist(nx, ny, this.spawnX, this.spawnY) < 110 && !game.zone.isBlocked(nx, ny, this.r)) { this.x = nx; this.y = ny; }
502:     else this.patrolAngle += Math.PI * 0.7;
503:   }
504: 
505:   moveToward(tx, ty, speed, dt, game) {
506:     const n = norm(tx - this.x, ty - this.y);
507:     const nx = this.x + n.x * speed * dt, ny = this.y + n.y * speed * dt;
508:     if (!game.zone.isBlocked(nx, ny, this.r)) { this.x = nx; this.y = ny; }
509:     else {
510:       const perp = { x: -n.y, y: n.x };
511:       const px = this.x + perp.x * speed * dt, py = this.y + perp.y * speed * dt;
512:       if (!game.zone.isBlocked(px, py, this.r)) { this.x = px; this.y = py; }
513:     }
514:   }
515: 
516:   startWindup(duration, type) {
517:     this.state = 'windup'; this.stateTime = 0; this.windup = duration; this.windupMax = duration;
518:     this.pattern = type;
519:     this.telegraph = { type, x: this.x, y: this.y, angle: this.facing, range: this.def.range + 40, radius: this.r + 60, timer: duration, duration, color: this.def.colors?.glow || '#ff8a5c' };
520:   }
521: 
522:   executeAttack(game, ang, d) {
523:     const p = game.player;
524:     const type = this.pattern;
525:     this.telegraph = null;
526:     if (type === 'melee') {
527:       const hit = dist(this.x, this.y, p.x, p.y) < this.def.range + 26 && Math.abs(angleDiff(this.facing, angleTo(this.x, this.y, p.x, p.y))) < 1.2;
528:       if (hit) game.damagePlayer(this.atk, { source: this, element: this.def.element, knockback: { x: Math.cos(this.facing), y: Math.sin(this.facing) } });
529:       game.spawnSlash(this.x, this.y, this.facing, this.def.range + 30, this.def.colors?.glow || '#ff8a5c', 0.22);
530:       game.audio.sfx('slash');
531:       this.attackCooldown = 1.1 + Math.random() * 0.6;
532:       this.state = 'recover'; this.stateTime = 0;
533:     } else if (type === 'ranged') {
534:       const n = norm(p.x - this.x, p.y - this.y);
535:       game.spawnProjectile({ x: this.x, y: this.y - 12, vx: n.x * 280, vy: n.y * 280, r: 9, damage: this.atk * 0.9, team: 'enemy', element: this.def.element, color: this.def.colors?.glow || '#b48cff', life: 2.4, source: this });
536:       game.audio.sfx('spell_dark');
537:       this.attackCooldown = 2 + Math.random() * 1.2;
538:       this.state = 'recover'; this.stateTime = 0;
539:     } else if (type === 'dash') {
540:       this.state = 'dash'; this.stateTime = 0;
541:       game.audio.sfx('dodge');
542:     }
543:   }
544: 
545:   updateBoss(dt, game, d, ang) {
546:     const p = game.player;
547:     if (this.state === 'windup') {
548:       this.windup -= dt;
549:       if (this.telegraph) {
550:         this.telegraph.timer = this.windup;
551:         this.telegraph.x = this.x; this.telegraph.y = this.y;
552:         this.telegraph.angle = ang;
553:       }
554:       if (this.windup <= 0) this.executeBossPattern(game, ang, d);
555:       return;
556:     }
557:     if (this.state === 'recover') {
558:       this.stateTime += dt;
559:       if (this.stateTime > Math.max(0.35, 0.8 - this.phase * 0.12)) { this.state = 'chase'; this.attackCooldown = Math.max(0.6, 1.6 - this.phase * 0.2); }
560:       return;
561:     }
562:     // fase
563:     const ratio = this.hp / this.maxHP;
564:     const newPhase = ratio < 0.3 ? 3 : ratio < 0.6 ? 2 : 1;
565:     if (newPhase > this.phase) {
566:       this.phase = newPhase;
567:       game.onBossPhase(this);
568:       this.attackCooldown = 0.8;
569:       game.spawnParticles(this.x, this.y, 30, this.def.colors?.glow || '#ff8a5c', 180, 1, 4);
570:     }
571:     const speed = this.speed * (1 + (this.phase - 1) * 0.18) * (this.statuses.slow > 0 ? 0.55 : 1);
572:     if (this.state !== 'windup') {
573:       if (d > 150) this.moveToward(p.x, p.y, speed, dt, game);
574:       else if (d < 90) this.moveToward(p.x, p.y, -speed * 0.5, dt, game);
575:       if (this.attackCooldown <= 0) this.chooseBossPattern(game, d);
576:     }
577:   }
578: 
579:   chooseBossPattern(game, d) {
580:     const patterns = this.def.attacks || [];
581:     const usable = patterns.filter(a => {
582:       if (a.type === 'melee' && d > 220) return false;
583:       if (a.type === 'ring' && d < 60) return false;
584:       return true;
585:     });
586:     if (!usable.length) return;
587:     let pick = choose(usable);
588:     if (pick.id === this.lastPattern && usable.length > 1) pick = choose(usable);
589:     this.lastPattern = pick.id;
590:     this.pattern = pick;
591:     this.windup = Math.max(0.4, pick.windup - (this.phase - 1) * 0.12);
592:     this.windupMax = this.windup;
593:     this.state = 'windup'; this.stateTime = 0;
594:     const color = pick.color || this.def.colors?.glow || '#ff8a5c';
595:     this.telegraph = {
596:       type: pick.type, x: this.x, y: this.y, angle: this.facing,
597:       range: pick.range || 160, width: pick.width || 40, radius: pick.radius || 150,
598:       timer: this.windup, duration: this.windup, color, pattern: pick,
599:     };
600:     game.audio.sfx('roar');
601:   }
602: 
603:   executeBossPattern(game, ang, d) {
604:     const p = game.player;
605:     const a = this.pattern;
606:     this.telegraph = null;
607:     this.state = 'recover'; this.stateTime = 0;
608:     const dmgMul = 1 + (this.phase - 1) * 0.18;
609:     if (!a) return;
610:     if (a.type === 'melee') {
611:       if (dist(this.x, this.y, p.x, p.y) < (a.range || 160) + 30 && Math.abs(angleDiff(ang, angleTo(this.x, this.y, p.x, p.y))) < 1.4) {
612:         game.damagePlayer(this.atk * a.damage * dmgMul, { source: this, element: this.def.element, knockback: { x: Math.cos(ang), y: Math.sin(ang) } });
613:       }
614:       game.spawnSlash(this.x, this.y, ang, a.range || 160, a.color, 0.3, 18);
615:       game.audio.sfx('heavy');
616:     } else if (a.type === 'aoe') {
617:       if (dist(this.x, this.y, p.x, p.y) < (a.radius || 150) + p.r) {
618:         game.damagePlayer(this.atk * a.damage * dmgMul, { source: this, element: this.def.element, knockback: { x: p.x - this.x, y: p.y - this.y } });
619:         if (a.burn) game.applyPlayerStatus('burn', a.burn);
620:         if (a.stun) game.applyPlayerStatus('slow', a.stun);
621:         if (a.root) game.applyPlayerStatus('slow', a.root);
622:       }
623:       game.spawnRing(this.x, this.y, a.radius || 150, a.color, 0.5);
624:       game.shake(12, 0.35);
625:       game.audio.sfx('heavy');
626:     } else if (a.type === 'beam') {
627:       const hit = game.lineHit(this.x, this.y, ang, a.range || 400, a.width || 40, p.x, p.y, p.r);
628:       if (hit) game.damagePlayer(this.atk * a.damage * dmgMul, { source: this, element: this.def.element });
629:       game.spawnBeam(this.x, this.y, ang, a.range || 400, a.width || 40, a.color, 0.45);
630:       game.audio.sfx('spell');
631:     } else if (a.type === 'ring') {
632:       if (dist(this.x, this.y, p.x, p.y) < (a.radius || 260) + p.r && dist(this.x, this.y, p.x, p.y) > 70) {
633:         game.damagePlayer(this.atk * a.damage * dmgMul, { source: this, element: this.def.element, knockback: { x: p.x - this.x, y: p.y - this.y } });
634:       }
635:       game.spawnRing(this.x, this.y, a.radius || 260, a.color, 0.6, true);
636:       game.audio.sfx('roar');
637:     } else if (a.type === 'projectiles') {
638:       const count = (a.count || 5) + (this.phase - 1) * 2;
639:       const spread = a.spread || 0.7;
640:       for (let i = 0; i < count; i++) {
641:         const t = count === 1 ? 0 : i / (count - 1) - 0.5;
642:         const aa = ang + t * spread;
643:         game.spawnProjectile({ x: this.x, y: this.y - 20, vx: Math.cos(aa) * (a.speed || 280), vy: Math.sin(aa) * (a.speed || 280), r: 10, damage: this.atk * a.damage * dmgMul, team: 'enemy', element: this.def.element, color: a.color, life: 3, source: this });
644:       }
645:       game.audio.sfx('spell_dark');
646:     } else if (a.type === 'summon') {
647:       for (let i = 0; i < (a.count || 2); i++) {
648:         const aa = ang + (i - ((a.count || 2) - 1) / 2) * 1.2;
649:         game.spawnEnemy(a.enemy, this.x + Math.cos(aa) * 90, this.y + Math.sin(aa) * 90, { summoned: true });
650:       }
651:       game.spawnRing(this.x, this.y, 160, a.color, 0.5);
652:       game.audio.sfx('portal');
653:     }
654:   }
655: 
656:   takeDamage(amount, game, opts = {}) {
657:     if (this.dead) return 0;
658:     let dmg = amount;
659:     if (opts.element && ELEMENTS[opts.element]) {
660:       if (ELEMENTS[opts.element].strong?.includes(this.def.element)) dmg *= 1.25;
661:       if (ELEMENTS[opts.element].weak?.includes(this.def.element)) dmg *= 0.8;
662:       if (ELEMENTS[this.def.element]?.weak?.includes(opts.element)) dmg *= 1.2;
663:     }
664:     dmg *= 100 / (100 + this.defense * 1.4);
665:     if (this.statuses.mark > 0) dmg *= 1.2;
666:     dmg = Math.max(1, Math.round(dmg));
667:     this.hp -= dmg;
668:     this.hitFlash = 1;
669:     this.aggro = true;
670:     this.poise -= dmg * (opts.heavy ? 1.6 : 1) + 3;
671:     if (this.poise <= 0 && !this.boss) {
672:       this.stagger = 1.4 + (opts.heavy ? 0.4 : 0);
673:       this.poise = this.maxPoise;
674:       game.addText(this.x, this.y - this.r - 34, 'ATURDIDO', '#ffe9a8', 13);
675:       game.audio.sfx('crit');
676:     } else if (this.poise <= 0 && this.boss) {
677:       this.stagger = 0.8;
678:       this.poise = this.maxPoise;
679:       game.addText(this.x, this.y - this.r - 34, 'GRIETA', '#ffe9a8', 13);
680:     }
681:     if (opts.status) this.applyStatus(opts.status, opts.statusDuration || 3, opts.statusPower || 4);
682:     game.addText(this.x + (Math.random() - 0.5) * 20, this.y - this.r - 20, (opts.crit ? '✦ ' : '') + dmg, opts.crit ? '#ffd06a' : '#fff3c4', opts.crit ? 18 : 13);
683:     game.spawnParticles(this.x, this.y - this.r * 0.4, opts.crit ? 10 : 5, this.def.colors?.glow || '#ffd06a', 90, 0.35, 2);
684:     game.audio.sfx(opts.crit ? 'crit' : 'hit');
685:     if (this.hp <= 0) this.die(game);
686:     return dmg;
687:   }
688: 
689:   applyStatus(name, duration, power) {
690:     if (!(name in this.statuses)) return;
691:     this.statuses[name] = Math.max(this.statuses[name], duration);
692:     if (name === 'burn') this.statusPower.burn = Math.max(this.statusPower.burn, power);
693:     if (name === 'poison') this.statusPower.poison = Math.max(this.statusPower.poison, power);
694:     if (name === 'weaken') this.atk *= 0.8;
695:   }
696: 
697:   die(game) {
698:     if (this.dead) return;
699:     this.dead = true; this.hp = 0; this.deathTime = 0; this.aggro = false;
700:     game.onEnemyKilled(this);
701:   }
702: }
