13:   city: { g1: '#5e4a42', g2: '#322522', g3: '#493733', path: '#7a5a48', path2: '#5e4438', water: '#ff5a36', water2: '#ffd166', edge: '#1e1512', fog: 'rgba(255,130,80,.05)', grade: 'rgba(255,120,60,.06)' },
