20: function rr(ctx, x, y, w, h, r) {
21:   r = Math.min(r, w / 2, h / 2);
22:   ctx.beginPath();
23:   ctx.moveTo(x + r, y);
24:   ctx.arcTo(x + w, y, x + w, y + h, r);
25:   ctx.arcTo(x + w, y + h, x, y + h, r);
26:   ctx.arcTo(x, y + h, x, y, r);
27:   ctx.arcTo(x, y, x + w, y, r);
28:   ctx.closePath();
29: }
30: function glow(ctx, x, y, r, color, alpha = 0.5) {
31:   const g = ctx.createRadialGradient(x, y, 0, x, y, r);
32:   g.addColorStop(0, color); g.addColorStop(0.35, color); g.addColorStop(1, 'rgba(0,0,0,0)');
33:   ctx.globalAlpha = alpha; ctx.fillStyle = g;
34:   ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();
35:   ctx.globalAlpha = 1;
36: }
37: function shadow(ctx, x, y, rx, ry, alpha = 0.28) {
38:   ctx.save(); ctx.globalAlpha = alpha; ctx.fillStyle = '#000';
39:   ctx.beginPath(); ctx.ellipse(x, y, rx, ry, 0, 0, TAU); ctx.fill(); ctx.restore();
40: }
41: function poly(ctx, pts, fill) {
42:   ctx.beginPath(); ctx.moveTo(pts[0][0], pts[0][1]);
43:   for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
44:   ctx.closePath(); ctx.fillStyle = fill; ctx.fill();
45: }
46: function lerpColor(a, b, t) {
47:   const pa = parseInt(a.slice(1), 16), pb = parseInt(b.slice(1), 16);
48:   const ar = pa >> 16, ag = (pa >> 8) & 255, ab = pa & 255;
49:   const br = pb >> 16, bg = (pb >> 8) & 255, bb = pb & 255;
50:   return `rgb(${Math.round(lerp(ar, br, t))},${Math.round(lerp(ag, bg, t))},${Math.round(lerp(ab, bb, t))})`;
51: }
