53: export class Renderer {
54:   constructor(canvas, titleCanvas, cineCanvas) {
55:     this.canvas = canvas;
56:     this.ctx = canvas.getContext('2d');
57:     this.titleCanvas = titleCanvas;
58:     this.titleCtx = titleCanvas?.getContext('2d');
59:     this.cineCanvas = cineCanvas;
60:     this.cineCtx = cineCanvas?.getContext('2d');
61:     this.dpr = 1;
62:     this.w = 0; this.h = 0;
63:     this.zoom = 1;
64:     this.camera = { x: 0, y: 0, tx: 0, ty: 0, shake: 0, shakeTime: 0, sx: 0, sy: 0 };
65:     this.zoneBg = null;
66:     this.zoneBgId = null;
67:     this.ambient = [];
68:     this.lastZoneId = null;
69:     this.resize();
70:     window.addEventListener('resize', () => this.resize());
71:   }
72: 
73:   resize() {
74:     const dpr = Math.min(window.devicePixelRatio || 1, 2);
75:     this.dpr = dpr;
76:     this.w = window.innerWidth;
77:     this.h = window.innerHeight;
78:     this.canvas.width = Math.floor(this.w * dpr);
79:     this.canvas.height = Math.floor(this.h * dpr);
80:     this.canvas.style.width = this.w + 'px';
81:     this.canvas.style.height = this.h + 'px';
82:     if (this.titleCanvas) {
83:       this.titleCanvas.width = Math.floor(this.w * dpr);
84:       this.titleCanvas.height = Math.floor(this.h * dpr);
85:       this.titleCanvas.style.width = this.w + 'px';
86:       this.titleCanvas.style.height = this.h + 'px';
87:     }
88:     if (this.cineCanvas) {
89:       this.cineCanvas.width = Math.floor(this.w * dpr);
90:       this.cineCanvas.height = Math.floor(this.h * dpr);
91:       this.cineCanvas.style.width = this.w + 'px';
92:       this.cineCanvas.style.height = this.h + 'px';
93:     }
94:     this.zoom = clamp(Math.max(this.w / 1280, this.h / 720), 0.8, 1.45);
95:   }
96: 
97:   screenToWorld(sx, sy) {
98:     const cssX = sx / this.dpr, cssY = sy / this.dpr;
99:     return { x: this.camera.x + cssX / this.zoom, y: this.camera.y + cssY / this.zoom };
100:   }
101:   worldToScreen(x, y) {
102:     return { x: (x - this.camera.x) * this.zoom, y: (y - this.camera.y) * this.zoom };
103:   }
104: 
105:   updateCamera(game, dt) {
106:     const p = game.player;
107:     if (!p) return;
108:     const vw = this.w / this.zoom, vh = this.h / this.zoom;
109:     const lookX = Math.cos(p.facing) * 40 + (p.vx || 0) * 0.12;
110:     const lookY = Math.sin(p.facing) * 24 + (p.vy || 0) * 0.08;
111:     let tx = p.x + lookX - vw / 2;
112:     let ty = p.y + lookY - vh / 2;
113:     const zone = game.zone;
114:     if (zone) {
115:       tx = clamp(tx, 0, Math.max(0, zone.w - vw));
116:       ty = clamp(ty, 0, Math.max(0, zone.h - vh));
117:     }
118:     const k = clamp(dt * 5.5, 0, 1);
119:     this.camera.x = lerp(this.camera.x, tx, k);
120:     this.camera.y = lerp(this.camera.y, ty, k);
121:     if (this.camera.shakeTime > 0) {
122:       this.camera.shakeTime -= dt;
123:       const s = this.camera.shake * (this.camera.shakeTime > 0 ? 1 : 0);
124:       this.camera.sx = (Math.random() - 0.5) * s * 2;
125:       this.camera.sy = (Math.random() - 0.5) * s * 2;
126:     } else { this.camera.sx = 0; this.camera.sy = 0; this.camera.shake = 0; }
127:   }
128: 
129:   // ============================================================
130:   // FONDO DE ZONA
131:   // ============================================================
132:   buildZoneBackground(zone) {
133:     if (this.zoneBgId === zone.id && this.zoneBg) return this.zoneBg;
134:     const c = document.createElement('canvas');
135:     c.width = zone.w; c.height = zone.h;
136:     const ctx = c.getContext('2d');
137:     const pal = THEMES[zone.theme] || THEMES.village;
138:     const rng = seededFor('bg', zone.id);
139: 
140:     // base
141:     const g = ctx.createLinearGradient(0, 0, zone.w, zone.h);
142:     g.addColorStop(0, pal.g1); g.addColorStop(0.55, pal.g3); g.addColorStop(1, pal.g2);
143:     ctx.fillStyle = g; ctx.fillRect(0, 0, zone.w, zone.h);
144: 
145:     if (zone.theme === 'void') {
146:       // abismo estrellado
147:       ctx.fillStyle = '#05030f'; ctx.fillRect(0, 0, zone.w, zone.h);
148:       for (let i = 0; i < 420; i++) {
149:         const x = rng() * zone.w, y = rng() * zone.h, a = 0.15 + rng() * 0.75, r = rng() * 1.8 + 0.4;
150:         ctx.fillStyle = `rgba(${180 + rng() * 60},${150 + rng() * 80},255,${a})`;
151:         ctx.beginPath(); ctx.arc(x, y, r, 0, TAU); ctx.fill();
152:       }
153:       // plataformas flotantes
154:       for (let i = 0; i < 14; i++) {
155:         const x = 100 + rng() * (zone.w - 200), y = 100 + rng() * (zone.h - 200);
156:         const rx = 100 + rng() * 220, ry = 50 + rng() * 90;
157:         const pg = ctx.createRadialGradient(x, y, 10, x, y, rx);
158:         pg.addColorStop(0, 'rgba(70,50,120,.75)'); pg.addColorStop(1, 'rgba(20,10,45,0)');
159:         ctx.fillStyle = pg; ctx.beginPath(); ctx.ellipse(x, y, rx, ry, rng() * 3, 0, TAU); ctx.fill();
160:         ctx.strokeStyle = 'rgba(160,120,255,.25)'; ctx.lineWidth = 2; ctx.stroke();
161:       }
162:     } else {
163:       // manchas de terreno
164:       for (let i = 0; i < 90; i++) {
165:         const x = rng() * zone.w, y = rng() * zone.h, rx = 60 + rng() * 220, ry = 30 + rng() * 130;
166:         ctx.save(); ctx.globalAlpha = 0.06 + rng() * 0.09;
167:         ctx.fillStyle = rng() < 0.5 ? pal.g2 : pal.g1;
168:         ctx.beginPath(); ctx.ellipse(x, y, rx, ry, rng() * 3, 0, TAU); ctx.fill(); ctx.restore();
169:       }
170:     }
171: 
172:     // textura
173:     const noise = this._noiseTexture();
174:     if (noise) {
175:       const pat = ctx.createPattern(noise, 'repeat');
176:       ctx.save(); ctx.globalAlpha = zone.theme === 'void' ? 0.12 : 0.18; ctx.fillStyle = pat; ctx.fillRect(0, 0, zone.w, zone.h); ctx.restore();
177:     }
178: 
179:     // senderos
180:     for (const path of zone.paths) {
181:       if (path.length < 2) continue;
182:       ctx.save(); ctx.lineJoin = 'round'; ctx.lineCap = 'round';
183:       ctx.strokeStyle = zone.theme === 'void' ? 'rgba(90,70,150,.65)' : pal.path2;
184:       ctx.lineWidth = 74; ctx.beginPath(); ctx.moveTo(path[0].x, path[0].y);
185:       for (let i = 1; i < path.length; i++) ctx.lineTo(path[i].x, path[i].y); ctx.stroke();
186:       ctx.strokeStyle = zone.theme === 'void' ? 'rgba(140,110,220,.45)' : pal.path;
187:       ctx.lineWidth = 58; ctx.beginPath(); ctx.moveTo(path[0].x, path[0].y);
188:       for (let i = 1; i < path.length; i++) ctx.lineTo(path[i].x, path[i].y); ctx.stroke();
189:       if (zone.theme !== 'void') {
190:         ctx.globalAlpha = 0.16; ctx.strokeStyle = '#fff'; ctx.lineWidth = 1;
191:         for (let i = 0; i < path.length - 1; i++) {
192:           const a = path[i], b = path[i + 1];
193:           const len = dist(a.x, a.y, b.x, b.y);
194:           for (let d = 20; d < len; d += 34) {
195:             const t = d / len, x = lerp(a.x, b.x, t) + (rng() - 0.5) * 34, y = lerp(a.y, b.y, t) + (rng() - 0.5) * 24;
196:             ctx.beginPath(); ctx.arc(x, y, 1.2 + rng() * 1.6, 0, TAU); ctx.stroke();
197:           }
198:         }
199:         ctx.globalAlpha = 1;
200:       }
201:       ctx.restore();
202:     }
203: 
204:     // suelos de ruinas / templos
205:     if (zone.theme === 'ruins' || zone.theme === 'temple' || zone.theme === 'library') {
206:       for (const path of zone.paths) {
207:         if (path.length < 2) continue;
208:         ctx.save(); ctx.globalAlpha = 0.25; ctx.strokeStyle = zone.theme === 'temple' ? '#cfd8e8' : '#c9c2a8';
209:         ctx.lineWidth = 48; ctx.setLineDash([28, 5]); ctx.beginPath(); ctx.moveTo(path[0].x, path[0].y);
210:         for (let i = 1; i < path.length; i++) ctx.lineTo(path[i].x, path[i].y); ctx.stroke(); ctx.restore();
211:       }
212:     }
213: 
214:     // agua base
215:     for (const w of zone.water) {
216:       const wg = ctx.createRadialGradient(w.x - w.rx * 0.3, w.y - w.ry * 0.3, 10, w.x, w.y, Math.max(w.rx, w.ry));
217:       wg.addColorStop(0, pal.water2); wg.addColorStop(0.45, pal.water); wg.addColorStop(1, '#0b2530');
218:       ctx.fillStyle = wg; ctx.beginPath(); ctx.ellipse(w.x, w.y, w.rx, w.ry, 0, 0, TAU); ctx.fill();
219:       ctx.strokeStyle = 'rgba(255,255,255,.18)'; ctx.lineWidth = 2; ctx.beginPath(); ctx.ellipse(w.x, w.y, w.rx * 0.97, w.ry * 0.97, 0, 0, TAU); ctx.stroke();
220:     }
221:     // lava base
222:     for (const l of zone.lava) {
223:       const lg = ctx.createRadialGradient(l.x - l.rx * 0.3, l.y - l.ry * 0.3, 5, l.x, l.y, Math.max(l.rx, l.ry));
224:       lg.addColorStop(0, '#fff3c4'); lg.addColorStop(0.25, pal.water2); lg.addColorStop(0.7, '#c93a1a'); lg.addColorStop(1, '#3a0a06');
225:       ctx.fillStyle = lg; ctx.beginPath(); ctx.ellipse(l.x, l.y, l.rx, l.ry, 0, 0, TAU); ctx.fill();
226:       ctx.strokeStyle = 'rgba(255,210,120,.55)'; ctx.lineWidth = 3; ctx.beginPath(); ctx.ellipse(l.x, l.y, l.rx * 0.96, l.ry * 0.96, 0, 0, TAU); ctx.stroke();
227:     }
228: 
229:     // decoración estática
230:     const decor = zone.decor.slice().sort((a, b) => a.y - b.y);
231:     for (const d of decor) this._drawDecor(ctx, d, zone, 0);
232:     // huellas / detalles
233:     if (zone.theme === 'village' || zone.theme === 'meadow') {
234:       for (let i = 0; i < 30; i++) {
235:         const x = rng() * zone.w, y = rng() * zone.h;
236:         ctx.save(); ctx.globalAlpha = 0.07; ctx.strokeStyle = '#fff'; ctx.lineWidth = 1;
237:         ctx.beginPath(); ctx.arc(x, y, 20 + rng() * 80, 0, TAU); ctx.stroke(); ctx.restore();
238:       }
239:     }
240: 
241:     this.zoneBg = c;
242:     this.zoneBgId = zone.id;
243:     return c;
244:   }
245: 
246:   _noiseTexture() {
247:     if (this._noise) return this._noise;
248:     const c = document.createElement('canvas'); c.width = c.height = 256;
249:     const ctx = c.getContext('2d'); const img = ctx.createImageData(256, 256);
250:     for (let i = 0; i < img.data.length; i += 4) {
251:       const v = Math.random() * 255;
252:       img.data[i] = img.data[i + 1] = img.data[i + 2] = v;
253:       img.data[i + 3] = Math.random() < 0.5 ? 18 : 0;
254:     }
255:     ctx.putImageData(img, 0, 0);
256:     this._noise = c; return c;
257:   }
258: 
259:   _drawDecor(ctx, d, zone, time) {
260:     const pal = THEMES[zone.theme] || THEMES.village;
261:     const sway = Math.sin(time * 1.5 + d.seed) * 2;
262:     switch (d.type) {
263:       case 'grass': {
264:         ctx.save(); ctx.strokeStyle = zone.theme === 'pass' || zone.theme === 'city' || zone.theme === 'fortress' ? 'rgba(120,90,60,.5)' : 'rgba(60,120,50,.5)';
265:         ctx.lineWidth = 1.2 * d.s; ctx.lineCap = 'round';
266:         for (let i = -1; i <= 1; i++) {
267:           ctx.beginPath(); ctx.moveTo(d.x + i * 3 * d.s, d.y);
268:           ctx.quadraticCurveTo(d.x + i * 5 * d.s + sway, d.y - 9 * d.s, d.x + i * 7 * d.s + sway, d.y - 15 * d.s); ctx.stroke();
269:         }
270:         ctx.restore(); break;
271:       }
272:       case 'flower': case 'flower2': {
273:         const colors = d.type === 'flower' ? ['#f4dfa3', '#e8a0c0', '#9fd6ff', '#ffd166'] : ['#dcc9ff', '#ff9a6a', '#c7f0e0'];
274:         const col = colors[Math.floor(d.seed) % colors.length];
275:         ctx.save(); ctx.translate(d.x, d.y); ctx.scale(d.s, d.s);
276:         ctx.strokeStyle = 'rgba(50,100,40,.6)'; ctx.lineWidth = 1;
277:         ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(sway * 0.2, -8); ctx.stroke();
278:         ctx.fillStyle = col;
279:         for (let i = 0; i < 5; i++) { const a = i / 5 * TAU; ctx.beginPath(); ctx.arc(Math.cos(a) * 2.4, -8 + Math.sin(a) * 2.4, 1.6, 0, TAU); ctx.fill(); }
280:         ctx.fillStyle = '#fff3c4'; ctx.beginPath(); ctx.arc(0, -8, 1.1, 0, TAU); ctx.fill();
281:         ctx.restore(); break;
282:       }
283:       case 'mushroom': case 'glowshroom': {
284:         ctx.save(); ctx.translate(d.x, d.y); ctx.scale(d.s, d.s);
285:         const col = d.type === 'glowshroom' ? '#7de8d0' : '#c95a4a';
286:         ctx.fillStyle = '#d8c9a8'; ctx.fillRect(-1.5, -8, 3, 8);
287:         ctx.fillStyle = col; ctx.beginPath(); ctx.ellipse(0, -8, 7, 4, 0, Math.PI, TAU); ctx.fill();
288:         if (d.type === 'glowshroom') glow(ctx, 0, -8, 18, 'rgba(125,232,208,.35)', 0.5);
289:         ctx.restore(); break;
290:       }
291:       case 'bush': case 'berryBush': {
292:         ctx.save(); ctx.translate(d.x, d.y); ctx.scale(d.s, d.s); shadow(ctx, 0, 0, 14, 5, 0.2);
293:         const bg = ctx.createRadialGradient(-3, -8, 2, 0, -6, 16);
294:         bg.addColorStop(0, zone.theme === 'pass' || zone.theme === 'city' ? '#6a5a44' : '#6fa356'); bg.addColorStop(1, '#2f5a32');
295:         ctx.fillStyle = bg;
296:         for (const [ox, oy, r] of [[-7, -5, 8], [5, -6, 8], [0, -11, 9], [-2, -2, 7]]) { ctx.beginPath(); ctx.arc(ox, oy, r, 0, TAU); ctx.fill(); }
297:         if (d.type === 'berryBush') { ctx.fillStyle = '#d94a4a'; for (const [ox, oy] of [[-5, -8], [5, -5], [1, -12]]) { ctx.beginPath(); ctx.arc(ox, oy, 1.8, 0, TAU); ctx.fill(); } }
298:         ctx.restore(); break;
299:       }
300:       case 'debris': case 'rubble': {
301:         ctx.save(); ctx.translate(d.x, d.y); ctx.scale(d.s, d.s);
302:         ctx.fillStyle = 'rgba(120,115,100,.45)';
303:         for (let i = 0; i < 4; i++) { const a = d.seed + i; ctx.fillRect(Math.cos(a) * 8, Math.sin(a) * 4 - 2, 5 + (i % 2) * 4, 3); }
304:         ctx.restore(); break;
305:       }
306:     }
307:   }
