309:   // ============================================================
310:   // RENDER PRINCIPAL
311:   // ============================================================
312:   render(game, dt) {
313:     const ctx = this.ctx;
314:     const dpr = this.dpr;
315:     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
316:     ctx.clearRect(0, 0, this.w, this.h);
317:     if (!game.zone || !game.player) {
318:       ctx.fillStyle = '#05070c'; ctx.fillRect(0, 0, this.w, this.h);
319:       return;
320:     }
321:     this.updateCamera(game, dt);
322:     const zoom = this.zoom;
323:     const zone = game.zone;
324:     const bg = this.buildZoneBackground(zone);
325:     ctx.save();
326:     ctx.translate(-this.camera.x * zoom + this.camera.sx, -this.camera.y * zoom + this.camera.sy);
327:     ctx.scale(zoom, zoom);
328: 
329:     // fondo
330:     ctx.drawImage(bg, 0, 0);
331: 
332:     // animaciones de agua y lava
333:     this._drawWaterAnim(ctx, zone, game.time);
334:     this._drawLavaAnim(ctx, zone, game.time);
335: 
336:     // recoger dibujables
337:     const drawables = [];
338:     for (const b of zone.buildings) drawables.push({ y: b.y + b.h, draw: () => this._drawBuilding(ctx, b, zone, game.time) });
339:     for (const p of zone.props) drawables.push({ y: p.y, draw: () => this._drawProp(ctx, p, zone, game.time) });
340:     for (const o of zone.objects) drawables.push({ y: o.y, draw: () => this._drawObject(ctx, o, zone, game, game.time) });
341:     for (const c of zone.chests) drawables.push({ y: c.y, draw: () => this._drawChest(ctx, c, game.time) });
342:     for (const s of zone.shrines) drawables.push({ y: s.y, draw: () => this._drawShrine(ctx, s, game, game.time) });
343:     for (const l of zone.loreStones) drawables.push({ y: l.y, draw: () => this._drawLoreStone(ctx, l, game.time) });
344:     for (const h of zone.herbs) if (!h.gathered) drawables.push({ y: h.y, draw: () => this._drawHerb(ctx, h, game.time) });
345:     for (const p of zone.portals) drawables.push({ y: p.y, draw: () => this._drawPortal(ctx, p, game, game.time) });
346:     for (const n of zone.npcs) drawables.push({ y: n.y, draw: () => this._drawNPC(ctx, n, game, game.time) });
