707: export class Companion {
708:   constructor(game, creatureId, level = 1) {
709:     this.game = game;
710:     this.id = creatureId;
711:     this.def = CREATURES[creatureId];
712:     this.level = level;
713:     this.x = game.player.x - 40; this.y = game.player.y + 30;
714:     this.r = 15;
715:     this.facing = 0;
716:     this.animTime = 0;
717:     this.attackCooldown = 1.5;
718:     this.abilityCooldown = 0;
719:     this.downed = false;
720:     this.downTimer = 0;
721:     this.hitFlash = 0;
722:     this.recalc(game);
723:     this.hp = this.maxHP;
724:   }
725:   recalc(game) {
726:     const sk = game.skillBonus ? game.skillBonus() : {};
727:     const mul = (1 + 0.22 * (this.level - 1)) * (1 + (sk.creatureStats || 0));
728:     this.maxHP = Math.round((this.def.base.hp + this.level * 8) * (1 + (sk.creatureStats || 0)));
729:     this.atk = Math.round((this.def.base.atk + this.level * 2.2) * (1 + (sk.creatureDmg || 0)));
730:     this.speed = 220 * this.def.base.spd;
731:     this.attackInterval = Math.max(0.7, 2.0 - this.level * 0.04) / (1 + (sk.creatureSpeed || 0));
732:     this.abilityCooldownMax = this.def.ability.cooldown;
733:     this.hp = Math.min(this.hp ?? this.maxHP, this.maxHP);
734:   }
735:   get ready() { return !this.downed; }
736:   update(dt, game) {
737:     this.animTime += dt;
738:     this.hitFlash = Math.max(0, this.hitFlash - dt * 4);
739:     this.attackCooldown = Math.max(0, this.attackCooldown - dt);
740:     this.abilityCooldown = Math.max(0, this.abilityCooldown - dt);
741:     if (this.downed) {
742:       this.downTimer -= dt;
743:       if (this.downTimer <= 0) { this.downed = false; this.hp = this.maxHP * 0.5; game.toast(`${this.def.name} se ha recuperado`, 'good'); }
744:       return;
745:     }
746:     const p = game.player;
747:     if (!p || p.dead) return;
