389: const SAVE_PREFIX = 'espada_celestial_v1_slot';
390: 
391: export class SaveSystem {
392:   static key(slot) { return SAVE_PREFIX + slot; }
393:   static list() {
394:     const out = [];
395:     for (let i = 0; i < 3; i++) {
396:       try {
397:         const raw = localStorage.getItem(SaveSystem.key(i));
398:         out.push(raw ? JSON.parse(raw) : null);
399:       } catch { out.push(null); }
400:     }
401:     return out;
402:   }
403:   static latest() {
404:     const list = SaveSystem.list().map((d, i) => d ? { ...d, slot: i } : null).filter(Boolean);
405:     list.sort((a, b) => (b.savedAt || 0) - (a.savedAt || 0));
406:     return list[0] || null;
407:   }
408:   static save(slot, data) {
409:     try { localStorage.setItem(SaveSystem.key(slot), JSON.stringify({ ...data, slot, savedAt: Date.now() })); return true; }
410:     catch (e) { console.warn('No se pudo guardar', e); return false; }
411:   }
412:   static load(slot) {
413:     try { const raw = localStorage.getItem(SaveSystem.key(slot)); return raw ? JSON.parse(raw) : null; } catch { return null; }
414:   }
415:   static delete(slot) { try { localStorage.removeItem(SaveSystem.key(slot)); } catch {} }
416:   static hasAny() { return SaveSystem.list().some(Boolean); }
417: }
