34: function segDist(px, py, ax, ay, bx, by) {
35:   const dx = bx - ax, dy = by - ay;
36:   const l2 = dx * dx + dy * dy;
37:   if (l2 === 0) return dist(px, py, ax, ay);
38:   let t = ((px - ax) * dx + (py - ay) * dy) / l2;
39:   t = clamp(t, 0, 1);
40:   return dist(px, py, ax + t * dx, ay + t * dy);
41: }
