276:       if (!arr) continue;
277:       for (const c of arr) if (dist2(x, y, c.x, c.y) < (c.r + r) ** 2) return true;
278:     }
279:     return false;
280:   }
281: 
282:   nearestInteractable(x, y, maxDist = 76) {
283:     let best = null, bestD = maxDist;
284:     for (const it of this.interactables) {
285:       if (it.kind === 'chest' && it.chest.opened) continue;
286:       if (it.kind === 'herb' && it.herb.gathered) continue;
287:       const d = dist(x, y, it.x, it.y);
288:       if (d < bestD) { bestD = d; best = it; }
289:     }
290:     return best;
291:   }
292: 
293:   getLore(id) { return LORE[id] || null; }
294: }
