299:   }
300:   get(id) {
301:     if (!this.zones[id]) {
302:       const def = ZONES[id];
303:       if (!def) throw new Error('Zona desconocida: ' + id);
304:       this.zones[id] = new Zone(def);
305:     }
306:     return this.zones[id];
307:   }
308:   reset(id) { delete this.zones[id]; }
