47: export function mix(a, b, t) {
48:   const pa = parseInt(a.slice(1), 16), pb = parseInt(b.slice(1), 16);
49:   const ar = pa >> 16, ag = (pa >> 8) & 255, ab = pa & 255;
50:   const br = pb >> 16, bg = (pb >> 8) & 255, bb = pb & 255;
51:   return `rgb(${Math.round(lerp(ar, br, t))},${Math.round(lerp(ag, bg, t))},${Math.round(lerp(ab, bb, t))})`;
52: }
