1139:   questEvent(type, id, data = {}) {
1140:     for (const qid of QUEST_ORDER) {
1141:       const q = this.quests[qid];
1142:       if (!q || q.state !== 'active') continue;
1143:       const def = QUESTS[qid];
1144:       const step = def.steps[q.step];
1145:       if (!step || !step.event) continue;
1146:       const ev = step.event;
1147:       if (ev.type !== type) continue;
1148:       if (type === 'reach') {
1149:         if (ev.zone !== id) continue;
1150:       } else if (type === 'kill') {
1151:         if (ev.tag !== id) continue;
1152:         q.progress = data.count || 0;
1153:         if (q.progress < (ev.count || 1)) continue;
1154:       } else if (type === 'collect') {
1155:         if (ev.id !== id) continue;
1156:         if (this.itemCount(id) < (ev.count || 1)) continue;
1157:       } else if (type === 'trial') {
1158:         if (ev.id !== id) continue;
1159:       } else {
1160:         if (ev.id !== id) continue;
1161:       }
1162:       this.advanceQuest(qid);
1163:     }
1164:   }
1165: 
1166:   checkCollectQuests() {
1167:     for (const qid of QUEST_ORDER) {
1168:       const q = this.quests[qid];
1169:       if (!q || q.state !== 'active') continue;
1170:       const ev = QUESTS[qid].steps[q.step]?.event;
1171:       if (ev?.type === 'collect' && this.itemCount(ev.id) >= (ev.count || 1)) this.advanceQuest(qid);
1172:     }
1173:   }
1174: 
1175:   advanceQuest(id) {
1176:     const q = this.quests[id];
1177:     const def = QUESTS[id];
1178:     if (!q || !def) return;
1179:     q.step++;
1180:     if (q.step >= def.steps.length) this.completeQuest(id);
1181:     else {
1182:       this.toast('Objetivo actualizado: ' + def.steps[q.step].text, 'good');
1183:       this.save(this.slot, true);
1184:     }
1185:   }
1186: 
1187:   completeQuest(id) {
1188:     const q = this.quests[id];
1189:     const def = QUESTS[id];
1190:     if (!q || q.state === 'done') return;
1191:     q.state = 'done';
1192:     q.step = def.steps.length;
1193:     // consumibles de misión
1194:     if (id === 's1') this.removeItem('herb_brisa', 3);
1195:     if (id === 's5') this.removeItem('star_shard', 3);
1196:     const r = def.rewards || {};
1197:     if (r.xp) this.gainXP(r.xp);
1198:     if (r.gold) this.addGold(r.gold);
1199:     for (const [item, count] of r.items || []) this.addItem(item, count);
1200:     if (def.onComplete?.flags) Object.assign(this.flags, def.onComplete.flags);
1201:     if (def.onComplete?.toast) this.toast(def.onComplete.toast, 'rare');
1202:     this.audio.sfx('quest');
1203:     this.ui.showBanner('MISIÓN COMPLETADA', def.title, def.onComplete?.toast || 'Tu leyenda crece.');
1204:     this.spawnRing(this.player.x, this.player.y, 90, '#ffe9a8', 0.8);
1205:     // progresión principal
1206:     if (id === 'm1') { this.startQuest('m2'); this.flags.nima_met = this.flags.nima_met || false; }
1207:     if (id === 'm2') this.startQuest('m3');
1208:     if (id === 'm3') { this.flags.tear_forged = true; }
1209:     if (id === 'm4') { this.flags.truth_known = true; }
1210:     this.save(this.slot, true);
1211:   }
