1273:     if (this.itemCount('crystal_shard') < shards) { this.toast(`Faltan ${shards - this.itemCount('crystal_shard')} fragmentos de cristal`, 'bad'); return false; }
1274:     this.player.gold -= goldCost;
1275:     this.removeItem('crystal_shard', shards);
1276:     this.itemUpgrades[itemId] = lvl + 1;
1277:     this.player.recalc(this);
1278:     this.audio.sfx('chest');
