      ${settingRow('Vibración de cámara', 'Sacudidas al recibir impactos', toggleControl('shake', s.shake))}
      ${settingRow('Números de daño', 'Muestra el daño flotante', toggleControl('damageNumbers', s.damageNumbers))}
