/* ---------- modal sheets (tienda, forja, opciones, guardado, finales) ---------- */
.sheet{position:relative;width:min(1000px,96vw);max-height:92vh;display:flex;flex-direction:column;background:linear-gradient(150deg,rgba(15,22,36,.985),rgba(6,9,16,.985));border:1px solid var(--line);border-radius:5px;box-shadow:0 30px 100px rgba(0,0,0,.82);overflow:hidden}
.sheet::after{content:'';position:absolute;inset:7px;border:1px solid rgba(217,180,106,.1);pointer-events:none;border-radius:3px}
.sheet-head{position:relative;z-index:1;display:flex;justify-content:space-between;align-items:flex-start;gap:18px;padding:16px 22px;border-bottom:1px solid var(--line-soft);flex:0 0 auto}
.sheet-head h2{font-family:var(--serif);font-weight:600;font-size:clamp(17px,2.2vw,25px);letter-spacing:.08em;margin:3px 0 0;color:var(--gold-bright)}
.sheet-head p{margin:4px 0 0;font-size:11px;line-height:1.45;color:var(--muted);max-width:720px}
.sheet-head .close-btn{width:34px;height:34px;border:1px solid var(--line);border-radius:3px;color:var(--gold);font-size:17px;flex:0 0 auto}
.sheet-head .close-btn:hover{background:rgba(217,180,106,.12)}
.sheet-body{position:relative;z-index:1;padding:16px 22px;overflow-y:auto;overscroll-behavior:contain;flex:1;min-height:0}
.sheet-body::-webkit-scrollbar{width:7px}.sheet-body::-webkit-scrollbar-thumb{background:rgba(217,180,106,.3);border-radius:4px}
.ending-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.choice-card{display:flex;gap:11px;text-align:left;padding:14px;border:1px solid var(--line-soft);background:rgba(255,255,255,.025);border-radius:4px;transition:.18s;align-items:flex-start}
.choice-card:hover:not(:disabled){border-color:var(--gold);background:rgba(217,180,106,.07);transform:translateY(-2px)}
.choice-card .cc-icon{font-size:25px;color:var(--gold);line-height:1;flex:0 0 auto;text-shadow:0 0 18px rgba(217,180,106,.5)}
.choice-card b{display:block;font-family:var(--serif);font-size:14px;letter-spacing:.06em;color:var(--gold-bright)}
.choice-card p{font-size:11px;line-height:1.5;color:#c9d0dd;margin:5px 0}
.choice-card small{display:block;font-size:9px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.choice-card em{display:block;font-style:normal;font-size:9px;color:var(--red);margin-top:6px;line-height:1.4}
.choice-card.locked{opacity:.45;filter:grayscale(.5);cursor:not-allowed}
.ending-status{display:flex;gap:16px;flex-wrap:wrap;justify-content:center;margin-top:14px;padding-top:10px;border-top:1px solid var(--line-soft);font-size:10px;color:var(--muted)}
.ending-status b{color:var(--gold-bright)}
.death-sheet{width:min(620px,94vw)}
@media (max-width:900px){
  .sheet{width:98vw;max-height:94vh}
  .sheet-head{padding:10px 13px}.sheet-head h2{font-size:16px}.sheet-head p{font-size:10px}
  .sheet-body{padding:10px 13px}
  .ending-grid{grid-template-columns:1fr}
}
@media (max-height:500px){
  .sheet-head{padding:8px 12px}.sheet-head h2{font-size:15px}.sheet-head p{display:none}
  .sheet-body{padding:8px 12px}
}

/* credits */
.credits-body{font-size:12px;line-height:1.65;color:#cbd2df;max-width:760px;margin:0 auto}

