.banner h3{font-family:var(--serif);font-size:clamp(20px,3.5vw,38px);font-weight:600;letter-spacing:.12em;margin:5px 0;color:var(--gold-bright);text-shadow:0 3px 30px #000,0 0 40px rgba(217,180,106,.3)}
